// Builds "docs/VierCRM Technical Documentation.docx" from the real source tree, the real test results and real screenshots.
//   npm run build && npm run e2e && npm run docs
import fs from 'node:fs';
import path from 'node:path';
import { execSync } from 'node:child_process';
import { Document, Packer, Paragraph, TextRun, Footer, Header, PageNumber, AlignmentType, LevelFormat } from 'docx';
import { H1, H2, H3, P, B, N, T, Code, Note, Img, gap, pageBreak, BLUE, INK } from './docs-helpers.mjs';
import { DESC } from './docs-descriptions.mjs';
import { renderDiagrams } from './docs-diagrams.mjs';

const root = path.resolve(import.meta.dirname, '..');
const exe = process.env.CHROMIUM || path.join(process.env.LOCALAPPDATA || '', 'ms-playwright/chromium-1248/chrome-win64/chrome.exe');
const OUT = path.join(root, 'docs', 'VierCRM Technical Documentation.docx');
const rel = p => p.split(path.sep).join('/');
const walk = (d, acc = []) => { for (const f of fs.readdirSync(d, { withFileTypes: true })) { if (['node_modules', 'dist', 'out', '.state'].includes(f.name)) continue; const p = path.join(d, f.name); if (f.isDirectory()) walk(p, acc); else acc.push(p); } return acc; };

// ------------------------------------------------------------------ facts read from the real project
const files = ['src', 'backend', 'scripts', 'tests'].flatMap(d => walk(path.join(root, d))).map(rel).map(p => rel(path.relative(root, p))).filter(p => /\.(ts|tsx|mjs|css)$/.test(p)).sort();
const info = Object.fromEntries(files.map(f => {
  const text = fs.readFileSync(path.join(root, f), 'utf8'); const lines = text.split('\n').length;
  const exports = [...text.matchAll(/^export (?:async )?(?:function|const|class|interface|type) ([A-Za-z0-9_]+)/gm)].map(m => m[1]);
  const imports = [...text.matchAll(/from '(\.{1,2}\/[^']+)'/g)].map(m => { const base = path.posix.normalize(path.posix.join(path.posix.dirname(f), m[1])); return ['.ts', '.tsx', '.mjs', '.js', '/index.ts'].map(e => base + e).find(c => files.includes(c)) || base; });
  return [f, { lines, exports, imports: [...new Set(imports)] }];
}));
const usedBy = {}; for (const [f, i] of Object.entries(info)) for (const d of i.imports) (usedBy[d] ||= []).push(f);
const missing = files.filter(f => !DESC[f]); if (missing.length) { console.error('No description for:\n  ' + missing.join('\n  ')); process.exit(1); }
const totalLines = Object.values(info).reduce((a, b) => a + b.lines, 0); const srcLines = Object.entries(info).filter(([f]) => f.startsWith('src/')).reduce((a, [, b]) => a + b.lines, 0);

let unit = { files: [], total: 0 };
try {
  const tmp = path.join(root, 'tests', 'e2e', 'out', 'vitest.json'); fs.mkdirSync(path.dirname(tmp), { recursive: true });
  try { execSync(`npx vitest run --reporter=json --outputFile="${tmp}"`, { cwd: root, stdio: 'pipe' }); } catch { /* the json is written even when tests fail */ }
  const j = JSON.parse(fs.readFileSync(tmp, 'utf8')); unit.total = j.numTotalTests; unit.passed = j.numPassedTests; unit.failed = j.numFailedTests;
  unit.files = j.testResults.map(r => ({ name: rel(path.relative(root, r.name)), n: r.assertionResults.length, titles: r.assertionResults.map(a => a.title) }));
} catch (e) { console.warn('could not read unit test results:', e.message); }
let e2e = { total: 0, failed: 0, results: [], at: '' };
try { e2e = JSON.parse(fs.readFileSync(path.join(root, 'tests/e2e/out/report.json'), 'utf8')); } catch { console.warn('no e2e report found – run npm run e2e first'); }
const shot = n => { const p = path.join(root, 'tests/e2e/out', n); return fs.existsSync(p) ? p : null; };
const when = new Date().toISOString().slice(0, 10);
let bench = null; try { bench = JSON.parse(fs.readFileSync(path.join(root, 'tests/perf/out/summary.json'), 'utf8')); } catch { console.warn('no benchmark summary – run npm run bench and node scripts/bench-summary.mjs'); }
/** JavaScript the browser must read before the app shows anything: the entry plus its static imports (lazy pages are not counted). */
function firstLoadKB(entry) {
  const seen = new Set(); const q = [entry]; let bytes = 0;
  while (q.length) { const f = q.pop(); if (seen.has(f)) continue; seen.add(f); const full = path.join(root, 'dist', f); if (!fs.existsSync(full)) continue; bytes += fs.statSync(full).size;
    for (const m of fs.readFileSync(full, 'utf8').matchAll(/from\s*["'](\.[^"']+)["']|(?:^|[;}\n])\s*import\s*["'](\.[^"']+)["']/g)) q.push(path.posix.normalize(path.posix.join(path.posix.dirname(f), m[1] || m[2]))); }
  return Math.round(bytes / 1024);
}
const distKB = d => { try { return Math.round(fs.readdirSync(path.join(root, 'dist', d)).reduce((a, f) => a + fs.statSync(path.join(root, 'dist', d, f)).size, 0) / 1024); } catch { return 0; } };
const jsFirst = firstLoadKB('app.js'), jsSide = firstLoadKB('sidepanel.js'); const fontFiles = fs.existsSync(path.join(root, 'dist/assets')) ? fs.readdirSync(path.join(root, 'dist/assets')).filter(f => /woff2?$/.test(f)) : [];

const img = await renderDiagrams(path.join(root, 'docs/img'), exe);

// ------------------------------------------------------------------ content
const c = [];
const add = (...x) => c.push(...x.flat());
const fig = (name, w, cap) => { const p = shot(name); if (p) add(Img(p, w, cap)); };

// ---- cover
add(new Paragraph({ spacing: { before: 2400, after: 120 }, children: [new TextRun({ text: 'VierCRM', font: 'Jost', bold: true, size: 84, color: BLUE })] }),
  new Paragraph({ spacing: { after: 120 }, children: [new TextRun({ text: 'Technical Documentation', font: 'Jost', size: 44, color: INK })] }),
  new Paragraph({ spacing: { after: 600 }, children: [new TextRun({ text: 'Airtable-style CRM with bases for people, companies and researchers, a general list scraper, automatic publication research and e-mail automation – a Chrome Extension for VierApparatus', font: 'Calibri', size: 26, color: '4A4546' })] }),
  T(['', ''], [['Version', '0.3.0 – Google Maps scraping with website e-mail finding and a Places base; earlier: bases and templates, generic scraping, automatic research, website styling, performance pass, fixes from a real-site test (0.1.0 was the first MVP)'], ['Document built', when], ['Source', `${files.filter(f => f.startsWith('src/')).length} source files · ${srcLines.toLocaleString('en')} lines in src/ · ${totalLines.toLocaleString('en')} lines including tests, scripts and backend`], ['Tests at build time', `${unit.passed ?? '?'} / ${unit.total} unit tests · ${e2e.total - e2e.failed} / ${e2e.total} browser checks`], ['Brand', 'VierApparatus – #4570B6 · #CAEBFB · #231F20 · Jost']], [25, 75]),
  gap(), Note('This document describes the code that exists. Every statement about behaviour is backed either by the source file named next to it or by a test listed in Appendix A. Where something is **not** implemented, or implemented but **not tested against the real service**, it says so (see section 1.3 and section 22).', 'info'), pageBreak());

// ---- contents
add(H1('Contents'), ...['1 Project overview', '2 Architecture', '3 Folder structure', '4 File-by-file documentation', '5 Chrome Extension architecture', '6 Scraping engine', '7 Pagination', '8 Field mapping', '9 Database and bases', '10 Views', '11 Formula system', '12 Automation engine', '13 Publication discovery', '14 Publication attachment management', '15 Email integration', '16 Brevo analytics', '17 Gmail integration', '18 Security', '19 Installation', '20 Configuration', '21 Troubleshooting', '22 Known limitations', '23 Future improvements', '24 Visual identity', '25 Performance and load speed', '26 Google Maps scraping', 'Appendix A – Test results', 'Appendix B – Example workflows and samples', 'Appendix C – Message reference'].map(t => P(t)), pageBreak());

// ---- 1 overview
add(H1('1 Project overview'),
  P('VierCRM is a Chrome Extension (Manifest V3) that combines five things VierApparatus needs to find and reach customers – researchers who buy laboratory equipment, but equally companies, contacts from LinkedIn or Apollo exports, or any other list. It is built around **bases**: a base is one list of records (people, companies, anything) with its own fields, views and duplicate rules. Three are created for you – **Researchers**, **Contacts** and **Companies** – and you add more with **＋ Add base**. Nothing in the program is specific to one kind of list; the research features (latest publication, DOI, PDF …) are an add-on that any base can have.'),
  ...B(['**An Airtable-style database** inside the browser: bases (tables), typed fields, views, filters, sorts, formula fields, record panels and CSV import / export, kept in IndexedDB.', '**A list scraper** that reads staff directories, company listings and other repeating lists: it detects each entry, opens its detail page, extracts what is there – including every “Label: value” row, which fills the field of the same name – and follows pagination. Each scrape is saved into the base you choose in the **Save to base** selector. Its design is taken from the existing LinkedIn job-listing scraper.', '**A publication research module** that finds a person’s latest publication from OpenAlex, Crossref, Semantic Scholar, PubMed, Google Scholar and ResearchGate, refuses to guess between people with the same name, and looks for a lawful full-text PDF. It runs **automatically** for every record that has a name but no publication.', '**An automation engine** (trigger → conditions → actions) with loop prevention, duplicate prevention, test mode and a history.', '**E-mail sending and analytics** through Brevo (with open / click / bounce / unsubscribe tracking) or Gmail (send only), with guard rails against sending by accident.']),
  H2('1.1 What “reusing the job scraper” means'),
  P('The existing job-automation project (`linkedin-job-assistant`) was read, not modified. VierCRM is a new folder with its own code. What carries over is the **approach** that already works there – find a repeating list, climb from each link to its card, read the card, open the detail page from the same site, fall back to a hidden tab for pages that only exist after JavaScript runs, follow Next / numbered / Load-more / infinite pagination, and keep a seen-set – re-expressed in TypeScript for researchers. Section 6 maps each job-scraper idea to its VierCRM counterpart.'),
  H2('1.2 Principles that shaped the code'),
  ...B(['**Never invent data.** A field the page does not state stays empty; a lookup fills only an empty cell; downstream fields never run on an empty upstream field.', '**A name is not an identity.** Author matches are scored; below the bar the user chooses.', '**Lawful sources only.** No Sci-Hub or shadow libraries, no paywall bypass, no CAPTCHA bypass.', '**Nothing is sent without deliberate activation.** Automations are created off and in test mode; a global switch gates all sending.', '**No AI field mapping.** Extraction is selectors, structure and patterns, as requested.', '**Data stays local.** IndexedDB for data, `chrome.storage.local` for secrets; the only outgoing calls are the research / e-mail APIs you configure.']),
  H2('1.3 Feature status at a glance'),
  P('**Status key.** *Tested (automated)* = covered by the unit tests and / or the browser test in Appendix A. *Fake-tested* = exercised against a local imitation of the documented API, never against the real service. *Live-verified* = checked against the real public service (read-only). *Not verified* = written but never run against the real service. *Not implemented* = planned only.'),
  T(['Area', 'Feature', 'Status'], [
    ['Extension', 'MV3 service worker, side panel page, full-page app, content script, floating control, element picker', 'Tested (automated) in real Chromium. The side panel is rendered as a page; Chrome’s own docking of the panel is not driven by the test.'],
    ['Bases', 'Starter bases Researchers / Contacts / Companies; “＋ Add base” from four templates; semantic field keys so scraping, e-mail and research work in any base; research fields as an add-on for any base; Manage-bases page; upgrade from 0.1.0 keeps every record', 'Tested (automated)'],
    ['Database', 'Bases, 17 field types, default views per template (11 for Researchers), custom views, filters (AND / OR / NOT, nested), sorts, search, field manager, record panel', 'Tested (automated)'],
    ['Database', 'Formula fields (25 functions), conditional logic', 'Tested (automated)'],
    ['Database', 'CSV import / export, backup / restore incl. PDFs, duplicate detection with rules', 'Tested (automated). Duplicate rules can be switched on / off; a rule editor for custom rules is not implemented.'],
    ['Database', 'Workspaces', 'Data model and seeding exist (one workspace, “VierApparatus”). Creating further workspaces in the UI is not implemented.'],
    ['Scraping', 'Directory detection, profile extraction, e-mail / phone detection (incl. obfuscated and Cloudflare-encoded), CSS / XPath mappings, constants, picker', 'Tested (automated) on the fictional fixture site. Real university sites vary widely: expect to tune some configurations.'],
    ['Scraping', 'Any list, not only people (companies, products, leads): relaxed entry detection, website / industry / size / location, generic mailboxes accepted, “Label: value” rows fill fields of the same name, “Save to base” chooser with “＋ New base…”', 'Tested (automated) on a fictional supplier directory. Apollo and LinkedIn were not scraped (section 6.8).'],
    ['Scraping', 'Pagination: Next links, numbered, URL pattern, Load more, infinite scroll, in-page Next buttons; limits; pause / resume / stop', 'Tested (automated)'],
    ['Scraping', 'Resume after the browser or service worker restarts mid-run', 'Not implemented (pause / resume works within a run).'],
    ['Research', 'OpenAlex, Crossref, PubMed, Europe PMC, arXiv, abstract by DOI', 'Live-verified read-only (section 13.6) and tested with fakes.'],
    ['Research', 'Semantic Scholar', 'Fake-tested. A live call without an API key was rate-limited (HTTP 429).'],
    ['Research', 'Unpaywall', 'Fake-tested. Requires your e-mail; not called live.'],
    ['Research', 'Google Scholar, ResearchGate', 'Tested against local look-alike pages in a real tab, including stopping at a human check. Real markup, rate limits and blocking were not tested; both sites restrict automated access and may block.'],
    ['Research', 'Institutional repositories / publisher pages', 'Generic: reads the standard `citation_pdf_url` tag. No per-repository adapters.'],
    ['Research', 'Automatic research: records with a name and no latest publication are looked up a few per minute (details only, no PDFs), the records on screen first; not-found retried after 7 days', 'Tested (automated) with the fakes; the live services are not called by the tests.'],
    ['Research', 'Author disambiguation with user choice; dependency-ordered research fields; PDF attachment, download and open', 'Tested (automated)'],
    ['Automation', '10 triggers, 9 actions, conditions, test mode, history, retry, loop and duplicate prevention, Wait, schedules', 'Tested (automated)'],
    ['E-mail', 'Templates, personalisation, preview, guard rails, Brevo send / verify / events', 'Fake-tested against a local imitation of Brevo’s documented API. **Not verified with a real Brevo key.**'],
    ['E-mail', 'Gmail OAuth, Send As, send', 'MIME building and rules unit-tested. **Not verified against a real Google account.**'],
    ['E-mail', 'Webhook backend', 'Unit-tested server and client. Not run behind a real public tunnel with Brevo.'],
    ['Interface', 'Website style (white surfaces, Jost, blue / ink buttons, sky headers), the website’s own icon and wordmark, a visible “Open app” button in the side panel', 'Tested (automated): computed styles, icon bytes and screenshots.'],
    ['Performance', 'Lazy pages, latin-only fonts, cached row values and search text, in-place record patches, progressive loading', 'Measured with 20 000 records (section 25).'],
    ['Sync', 'Cloud synchronisation', 'Not implemented (the design leaves room for it – section 9.6).'],
  ], [14, 50, 36]),
  pageBreak());

// ---- 2 architecture
add(H1('2 Architecture'), ...Img(img.architecture, 640, 'Figure 1 – Execution contexts and data flow'),
  H2('2.1 Execution contexts'),
  T(['Context', 'Code', 'Responsibilities', 'Why it is separate'], [
    ['Extension pages', '`src/ui` (React)', 'Side panel and full app: show data, edit it, start jobs. Write to IndexedDB directly and notify the worker.', 'They live only while open; they must not own long jobs.'],
    ['Background service worker', '`src/background`', 'Message router, scrape run, lookups, automations, e-mail, alarms. The only place that calls research and e-mail APIs.', 'Survives closing the panel; one place for API keys; MV3 requires event-driven logic here.'],
    ['Content script', '`src/content` + `src/scrape`', 'Reads the page being scraped: detect, fetch / render profiles, extract, report. Hosts the floating control and the element picker.', 'Needs the page’s DOM; injected on demand, never at install.'],
    ['IndexedDB / chrome.storage', '`src/core/db.ts`, `settings.ts`', 'Data and secrets.', 'Secrets are kept out of the database so they never reach backups, exports or logs.'],
    ['Optional backend', '`backend/webhook-server.mjs`', 'Receives Brevo webhooks and hands them to the extension.', 'Brevo must call a public URL, which an extension cannot provide (section 16).'],
  ], [16, 20, 38, 26]),
  H2('2.2 Data flow in one sentence'),
  P('A page (or the content script) produces data → the background worker or a page writes it to IndexedDB through `core/store.ts` → the store announces the change (BroadcastChannel for other open pages, `record:changed` to the worker) → the automation engine in the worker decides whether a trigger fires → actions write back with an origin tag so the engine can stop loops.'),
  H2('2.3 Design decisions'),
  ...B(['**IndexedDB, not chrome.storage, for data**: thousands of records, indexes by table, and Blob-sized PDFs. `unlimitedStorage` is requested.', '**The worker owns the engine**: pages forward changes (`setRemoteSink`); the worker also subscribes to its own writes (`onChange`).', '**Profiles are read in the background** (same-site `fetch`, or a hidden tab) so the directory page never navigates away – the requested “return to the directory” is satisfied by never leaving it.', '**Optional host permissions**: the extension installs with access to the research / e-mail APIs only; reading arbitrary websites is requested at the moment you start, and can be revoked.', '**Heuristics + explicit overrides**: automatic detection for speed, selectors and mappings when a site needs them.', '**Fields have a meaning (a `key`)**: `email`, `fullName`, `latestPublication` … The scraper, e-mail service, analytics and research find fields by key, not by id or name, so one piece of code serves every base. Field ids are unique per base; the original Researchers base keeps its `fld_*` ids so existing data and links survive.', '**A base is just a table**: the template only decides the starting fields, views and duplicate rules; afterwards fields can be added, renamed or removed freely, and the research add-on can be added to any base.', '**Pages are loaded when visited**: the shell is a few kilobytes; each page is its own chunk (section 25).']),
  pageBreak());

// ---- 3 folder structure
add(H1('3 Folder structure'),
  Code(['VierCRM/', '  package.json  tsconfig.json  vite.config.ts  vite.content.config.ts  vitest.config.ts', '  app.html  sidepanel.html            entry pages (Vite inputs)', '  public/manifest.json  public/icons/  public/brand/   copied into dist/ (icons are rendered from the website icon; brand/ holds the wordmark)', '  assets/        icon.svg – a copy of the VierApparatus website’s own icon', '  src/', '    core/        data model, IndexedDB, store, formulas, templates, filters, dedupe, CSV, dependencies, settings', '    scrape/      detect · extract · paginate · pageCrawler · selector · dom', '    research/    http · matching · sources · pageExtractors · keywords · fulltext · lookup · auto (automatic research)', '    automation/  engine', '    email/       brevo · gmail · service · analytics', '    background/  service worker', '    content/     injected content script', '    shared/      message types', '    ui/          React app, side panel, components (grid, table view, field manager, add-base …), pages, styles', '  backend/       webhook-server.mjs (optional)', '  samples/       sample CSV, scraping configuration, automation, template (all fictional)', '  scripts/       icon renderer, build check, samples, live API check, benchmark summary, documentation builder', '  tests/         unit/ · e2e/run.mjs · perf/bench.mjs · fixtures/site.mjs', '  docs/          this document + img/', '  dist/          the built extension (load this folder in Chrome)'].join('\n')),
  P('`npm run build` runs Vite twice: once for the pages and the service worker (ES modules), once for the content script (a single IIFE, because content scripts cannot be modules), then checks that `dist/` is complete.'), pageBreak());

// ---- 4 file by file
add(H1('4 File-by-file documentation'), P('Exports, dependencies and “used by” are read from the source files when this document is built; purpose and interaction text is written by hand (`scripts/docs-descriptions.mjs`) and the build fails if a file has no entry.'));
const groups = [['src/core', 'Core (data, logic without a UI)'], ['src/scrape', 'Scraping engine'], ['src/content', 'Content script'], ['src/shared', 'Shared messages'], ['src/research', 'Publication research'], ['src/automation', 'Automation'], ['src/email', 'E-mail'], ['src/background', 'Background worker'], ['src/ui', 'User interface'], ['src/vite', 'Build typings'], ['backend', 'Optional backend'], ['scripts', 'Scripts'], ['tests', 'Tests and fixtures']];
for (const [prefix, title] of groups) {
  const list = files.filter(f => f.startsWith(prefix)); if (!list.length) continue; add(H2(title));
  for (const f of list) {
    const [purpose, does, interacts] = DESC[f]; const i = info[f];
    add(H3(`${f}  ·  ${i.lines} lines`), P(`**Purpose.** ${purpose}`), P(`**What it implements.** ${does}`), P(`**Interaction.** ${interacts}`));
    const rows = []; if (i.exports.length) rows.push(['Exports', i.exports.slice(0, 18).map(e => `\`${e}\``).join(', ') + (i.exports.length > 18 ? ` … (+${i.exports.length - 18})` : '')]);
    if (i.imports.length) rows.push(['Depends on', i.imports.map(d => `\`${d}\``).join(', ')]); if (usedBy[f]?.length) rows.push(['Used by', usedBy[f].slice(0, 8).map(d => `\`${d}\``).join(', ') + (usedBy[f].length > 8 ? ` … (+${usedBy[f].length - 8})` : '')]);
    if (rows.length) add(T(['', ''], rows, [14, 86]), gap());
  }
}
add(pageBreak());

// ---- 5 extension architecture
add(H1('5 Chrome Extension architecture'),
  H2('5.1 Manifest'),
  T(['Entry', 'Value', 'Why'], [['`manifest_version`', '3', 'Required for new extensions.'], ['`background`', '`background.js`, `type: module`', 'Service worker with ES modules (shared chunks).'], ['`side_panel`', '`sidepanel.html`; `openPanelOnActionClick`', 'Panel stays open while you browse directories, Scholar and ResearchGate.'], ['`action`', 'icon only', 'Clicking opens the side panel; the full app opens from it.'], ['`content_security_policy`', '`script-src \'self\'; object-src \'self\'`', 'No remote or inline code; formulas are interpreted, never evaluated.'], ['`minimum_chrome_version`', '116', 'The side panel API.']], [22, 38, 40]),
  H2('5.2 Permissions and why each is requested'),
  T(['Permission', 'Reason'], [['`sidePanel`', 'The side panel.'], ['`storage`, `unlimitedStorage`', 'Secrets in `chrome.storage.local`; IndexedDB without the default quota pressure (PDF blobs).'], ['`scripting`', 'Inject the content script and run the Scholar / ResearchGate parsers in a tab.'], ['`activeTab`, `tabs`', 'Know the current tab’s URL and title; open, wait for and close hidden tabs; navigate to the next directory page.'], ['`alarms`', 'One-minute tick: resume Wait actions, run scheduled automations, sync Brevo.'], ['`identity`', 'Gmail OAuth with `launchWebAuthFlow`.'], ['`downloads`', 'Reserved for exports; downloads are currently made with blob links.'], ['Host permissions (standing)', 'api.openalex.org, api.crossref.org, api.semanticscholar.org, eutils.ncbi.nlm.nih.gov, api.unpaywall.org, www.ebi.ac.uk, api.brevo.com, gmail.googleapis.com, www.googleapis.com – the services VierCRM talks to.'], ['Optional host permissions', '`https://*/*`, `http://*/*` – requested once, when you start a scrape or a lookup that needs other sites (reading directories, downloading open-access PDFs). Not requested at install; revocable in Settings or chrome://extensions.']], [28, 72]),
  H2('5.3 Lifecycle and the MV3 service-worker limit'),
  P('A service worker is stopped after a short idle period. The scrape run keeps itself alive with a 20-second `getPlatformInfo` ping while it is running, and every page read keeps messages flowing. Run state is kept in memory plus `chrome.storage.session`; the last result is saved to IndexedDB. If Chrome is closed or the worker is killed mid-run, the run ends (it is **not** resumed automatically – section 22). Waits and schedules survive because they are stored (`pending` store, automation `lastRunAt`) and driven by the alarm.'),
  H2('5.4 Messaging'),
  P('Pages and content scripts talk to the worker with `chrome.runtime.sendMessage`; the worker answers with `{ ok, … }` or `{ ok: false, error }`, which the UI bridge turns into exceptions and toasts. The full list is in Appendix C. Two broadcast channels flow the other way: `scrape:progress` (to pages and to the floating control in the scraped tab) and `lookup:progress`.'),
  H2('5.5 Content script injection'),
  P('The content script is injected with `chrome.scripting.executeScript({ files: [\'content.js\'] })` immediately before use, on the tab being scraped and on hidden tabs used for profile rendering. A guard (`window.__vierCrm`) makes repeated injection harmless. It is one self-contained IIFE bundle.'),
  ...Img(img['scrape-flow'], 640, 'Figure 2 – One scrape: who talks to whom'), pageBreak());

// ---- 6 scraping
add(H1('6 Scraping engine'),
  H2('6.1 How it relates to the job scraper'),
  T(['Job scraper (`linkedin-job-assistant/content/capture.js`)', 'VierCRM'], [
    ['`genericJobLinks`: links that look like postings, grouped by URL shape; a list needs ≥ 2 (known ATS / strong path) or ≥ 3 members', '`detect.detectPeople`: links whose text looks like a person’s name, grouped by URL shape (`host + dirname`); a group needs ≥ 3 members, or ≥ 2 when ≥ 60 % sit under `/people/`, `/staff/`, `/profile/` …'],
    ['`cardRootFor`: climb until the parent contains another posting’s link', '`detect.cardRoot`: same climb, so a card holds exactly one person'],
    ['`repeatedBlockLinks`: fallback for sites with no recognisable URLs', '`detect.repeatedBlocks`: repeated sibling blocks that each hold a name (cards without profile links)'],
    ['`cardFacts` / `kvPairs`: company, place, salary from a card', '`detect.cardFacts` + `extract.labelled`: position, department, e-mail, phone from a card; `dt/dd` and `th/td` rows on profiles'],
    ['`fetchSameOrigin` with charset detection', '`content.fetchDoc` (charset-aware, adds a `<base>` so relative links resolve)'],
    ['Hidden-tab render for pages that only exist after JavaScript runs', '`background.renderInHiddenTab` + `crawl:extractHere`'],
    ['`findNextUrl` / `findNextButton` / `findLoadMore` / `expandList`', '`paginate.ts` (same logic, parameterised by Document and testable)'],
    ['`listContext`: on page 2+ a single link still counts as a list', '`DetectOpts.listContext` (minimum group size − 1)'],
    ['`navigateAndWait`: listener before navigation, only trust a “complete” that follows our own navigation', '`background.navigate` (same fix); fresh tabs ignore the stale `about:blank` “complete”'],
    ['Seen-set and “stop after N pages with nothing new”', '`PageState.seen` and `stopAfterEmptyPages`'],
    ['Duplicate fingerprint; lesson: agency reposts differ only by town', 'Duplicate rules; lesson applied: a name-based rule never merges two records with different e-mail or profile URL (`unlessDifferent`)'],
    ['Progress, Stop, Resume, per-site result', '`ScrapeProgress`, `scrape:pause/resume/stop`, floating control'],
  ], [48, 52]),
  H2('6.2 Detecting the entries on a page'),
  ...N(['If the configuration has a **card selector**, every match is a card (the profile link is `linkSelector`, else the first non-mailto link).', 'Otherwise gather every `a[href]` outside navigation, header, footer, aside, breadcrumbs and pagination. Keep links whose text (or a heading / `<strong>` / image alt inside) passes `looksLikeName`.', '**People lists** keep a link only when its text passes `looksLikeName`; **“any list”** (`kind: items`, used for companies, products, leads) keeps any link whose text is a plausible title (2–90 characters, not navigation such as “Next”, “Read more”, “Contact”). The rest of the detection is identical.', '`looksLikeName` accepts 2–5 tokens that are capitalised or name particles (van, de, bin, al …), accepts `Lovelace, Ada`, honorifics (Prof., Dr., Ir.) and degrees; it rejects digits, `@`, navigation words (“Read more”, “Staff”, “Department”) and job-title words (“Senior Researcher”).', 'Group by URL shape. A real list repeats, so single links (menus, “Home”, “News”) fall away; the largest group and any group at least half its size are kept (for lists split by letter).', 'Climb from each link to its card and read position / department (title and unit patterns), `mailto:` and `tel:` links.', 'If no link group exists, fall back to repeated blocks that each contain a name.']),
  H2('6.3 Extracting a profile'),
  P('Explicit mappings run first and always win. Then, per field:'),
  T(['Field', 'Where it is looked for (in order)'], [['Full name', 'JSON-LD `Person.name` → `h1` that looks like a name → the card’s name → `og:title` → `<title>` before the first separator'], ['E-mail', '`mailto:` links → Cloudflare `data-cfemail` (XOR-decoded) → `data-email` → text, including “name [at] domain [dot] edu” spellings. Generic role mailboxes (info@, office@, secretariat@ …) are **not** taken as the person’s address; with several candidates the one resembling the name wins.'], ['Phone', '`tel:` links → a line labelled Tel / Phone / Telephone … (value on the same line or the next line, as in `dt`/`dd`); “fax” lines are skipped; 7–15 digits.'], ['Position', 'JSON-LD `jobTitle` → labelled row (Position, Title, Rank …) → elements whose class says job-title / position / role → the line after the name that matches title words'], ['Department', 'Labelled row → class names → a line with department / faculty / school / institute / laboratory'], ['Institution', 'Labelled row → JSON-LD `worksFor` / `affiliation` → `<title>` suffix containing university / institute / college … → `og:site_name`; or your constant for the site'], ['Biography', 'JSON-LD description → the paragraphs under a Biography / About / Profile / Overview heading → `meta description` only when long and containing the person’s surname'], ['Research keywords', 'Labelled row → items under a Research interests / Areas of expertise / Keywords heading → JSON-LD `knowsAbout`'], ['Identity and publication links', 'Links to ORCID, Google Scholar profiles, ResearchGate profiles, Semantic Scholar authors, OpenAlex, Scopus (kept as identity evidence – used later to tell namesakes apart); DOI / PubMed / publisher links and links under a Publications heading (kept with the record)']], [20, 80]),
  Note('Anything not found stays empty. There is no AI step and no guessing of e-mail addresses from name patterns.', 'good'),
  H2('6.4 The crawl loop'),
  P('`pageCrawler.crawlPage` handles one page: wait up to 6 s for a JavaScript-drawn list, resolve the pagination mode for this page, expand the list (Load more / scroll), detect people, skip those already seen, and for each new one read the card, then the profile (same-site `fetch`; a hidden tab if the response is an empty shell or the profile is on another domain), emit the person, and wait a random delay. It returns the next URL, the updated seen-set and a stop reason. The worker injects the script again after navigating (`background.crawl`).'),
  H2('6.5 Saving people'),
  P('`store.intakePerson` saves one scraped entry into the **base chosen in the Scraper**. Values the extractor reports under a meaning (`fld_email`, `fld_website` …) are written to whichever field of **that** base has the key; values under a real field id (your own mappings) are written as they are; every “Label: value” pair found on the page fills the field with the same **name** (so a field you add, such as “Revenue”, is filled with no configuration; common synonyms such as Web → Website and Telephone → Phone are understood). It then splits the name, lower-cases the e-mail, sets Source URL, Scraping Date and Scraping Status (Scraped / Partial / Failed) where the base has those fields, sets Outreach Status to Not Contacted on creation, looks the person up in the duplicate index and either creates a record or **fills only empty cells** of the existing one. A failed re-scrape never downgrades a good record.'),
  ...Img(shot('02-contacts-grid.png') || img.architecture, 600, 'Figure 3 – The Researchers base after scraping the fictional fixture site (test data)'),
  H2('6.6 Companies and other lists'),
  P('Choose a base made from the **Companies** template (or any base), open the listing page and pick the configuration “Companies / any listing (auto-detect)” – choosing a Companies or Blank base switches to it for you. For each entry VierCRM opens the detail page and reads, in order: JSON-LD (`Organization`, `LocalBusiness` …), labelled rows (Website, Industry, Size, Location, Country, Address …), the first external link that looks like the company’s own website (social networks and map links are ignored), a **generic mailbox** such as info@ or sales@ (kept for companies, skipped for people), phone, and a description from the page or its meta description. Every “Label: value” row on the page is also offered to the fields of the base by name.'),
  ...Img(shot('13-companies-base.png') || img.architecture, 600, 'Figure 4 – Six fictional suppliers scraped from a list page and their detail pages into a new Companies base (test data)'),
  H2('6.7 Choosing where scraped data goes'),
  P('At the top of the Scraper (page and side panel) the **Save to base** selector lists every base with its record count, plus **＋ New base…**. The choice is remembered. The Start button says where the data will go (“Start → Suppliers”). Configuration parts that name fields (mappings, constants) belong to a base and are cleared when you switch. A base is chosen per scrape: the same list can be scraped into Researchers and, separately, into Contacts, and each gets its own copy under its own field ids.'),
  ...Img(shot('11a-sidepanel-scrape.png') || img.architecture, 300, 'Figure 5 – The side panel: “Save to base”, current website, Preview / Start (test data)'),
  H2('6.8 Apollo, LinkedIn and other logged-in sites'),
  Note('These were **not** scraped in any test. Apollo and LinkedIn are logged-in single-page applications whose terms restrict automated collection. VierCRM reads only what your own logged-in tab already shows, at the delays you set, and stops at a login wall, CAPTCHA or security check – it never tries to get past one. For large lists use the site’s own export and **Import CSV** in a base (columns are matched to fields by name; duplicates are skipped). If a page is a list that VierCRM does not detect, switch the configuration to manual: pick one card with ⌖ and map elements to fields by CSS selector or XPath.', 'warn'),
  H2('6.9 A real-site check: a university school’s people page'),
  P('After release the scraper was tried on a real school directory (a Drupal site whose cards link to a separate research-portal domain) and found **nothing**. Reproducing it with the saved page showed three separate causes, all fixed and covered by tests:'),
  ...N(['**A class on <body>.** The site’s cookie script adds a class such as “cookie-compliance-active” to the page body. The rule that skips navigation, footers and cookie banners matched the body itself, so every card counted as being inside a banner. The rule now never matches the page body, <html> or <main> (a saved copy of the page lacked the class, which is why the first unit test had passed).', '**An e-mail hidden in an attribute.** The portal shows only “name” in the page and has a script add the “@” and the dots; the address itself is stored base64-encoded in a `data-md5` attribute of a link with `href="#"`. The extractor now decodes base64 values of `data-*` attributes that decode to `mailto:…`. Nothing is guessed: if no such value exists the field stays empty.', '**A wait that never ends.** Profiles on another domain are read in a hidden tab, and the worker waited for the browser’s “complete” event, which also waits for every image and tracking script – on a slow or ad-heavy page that can take very long. It now also polls `document.readyState` and continues as soon as the DOM is ready. In a local replica of the site this took the first profile from failing four times in five to succeeding five times in five.']),
  P('**Second report on the same site: only the first page was read.** The scraper read page 1 and stopped with “next page did not load”. It is the same “complete” wait as in cause 3, this time in the navigation to the **next list page**: that page needs over 30 seconds to finish loading (images, trackers) although its list is there at once. Navigation now also polls the new document’s `readyState`. A browser test with a directory whose image never finishes loading reproduced the stop (8 of 23 people) before the fix and reads all 23 after it. Two smaller findings from the same report: a “Next” selector picked on the `<span>` inside the link now resolves to the link; and when several lists share a page (this site has three, all using the same `?page=` number, so one “Next” moves all three), a short list is no longer dropped because another list is bigger (the cut-off for the secondary lists went from half to a quarter of the largest). A scrape also only moves forward, so start it on the first page (no `?page=`).'),
  P('The real site was contacted only a few times (page fetches and one profile), and the browser tests of this check ran against a local copy; the site then stopped answering for a while, so no larger live run was made. Pagination (`?page=0, 1, 2 …`, “Next” link with `rel="next"`) was checked on the saved pages.'),
  H2('6.10 A stale copy of the script in an open tab'),
  P('A page already open is **not** reloaded when the extension is updated or reloaded, so the previous version’s content script stays in it. Until now the new copy refused to install (“install only once”), which meant a tab used for many test runs could keep running old code – and an old copy whose extension context had been reloaded no longer receives any messages. Every injection now installs itself and first switches off the previous copy. Copies from versions before this one cannot be switched off remotely: reload the page once after updating.'),
  H2('6.11 Honest limits'),
  ...B(['Detection is heuristic. Directories that show names only as images, behind a login, in iframes from another domain, or as free text without a repeating structure need manual selectors – or are not scrapable.', 'Name recognition is tuned for Latin-script names and common particles; names in other scripts are only found through user-supplied selectors.', 'Sites whose terms forbid automated access should not be scraped; VierCRM stops at a CAPTCHA, security check or login but cannot judge a site’s terms for you.']), pageBreak());

// ---- 7 pagination
add(H1('7 Pagination'),
  ...Img(img['scrape-flow'], 520, 'The page loop (repeated from section 5)').slice(0, 0),
  T(['Mode', 'How it works', 'Tested with'], [
    ['Auto (default)', 'Per page: a Next link or button → “next”; else a Load-more button → “loadMore”; else try infinite scroll.', 'All fixtures'],
    ['Next link', '`nextSelector` (if set) → `rel="next"` → link whose text / aria-label is Next / Volgende / Suivant / Weiter / Berikutnya / 次へ … → the numbered page after the current one.', '`/dir/static` (3 pages)'],
    ['Numbered pages', 'Current page found from `aria-current` / `.active`; the link with the next number is followed.', 'unit test'],
    ['URL pattern', '`urlTemplate` with `{page}` and `startPage`.', 'unit test'],
    ['Load more', 'Clicks the button until it disappears or a click adds nobody (6 s wait per click), up to “max scroll / load-more rounds”.', '`/dir/loadmore`'],
    ['Infinite scroll', 'Scrolls to the bottom; stops when a round adds nobody.', '`/dir/infinite`'],
    ['In-page Next button', 'Clicks the button and waits until the list changes; repeats in the same document.', '`/dir/spa`'],
    ['Single page', 'Reads the page and stops.', 'unit test'],
  ], [18, 56, 26]),
  H2('7.1 Limits and stop conditions'),
  T(['Setting', 'Meaning'], [['Max pages', 'Pages read, counting in-page turns.'], ['Max records', 'People read in the run (default 2 000).'], ['Max scroll / load-more rounds', 'Depth of one page’s expansion (default 15).'], ['Delay between profiles', 'Random pause, default 1.5–3.2 s.'], ['Stop after N pages with nobody new', 'Default 2; prevents endless loops on sites that repeat the last page.'], ['Also', 'The user pressing Stop; the next URL being one already read; the next page failing to load; the page not answering.']], [34, 66]),
  H2('7.2 How the next page is found'),
  P('For every page, in this order; the first that gives an address wins. If something says “this is the last page” the search stops there and nothing is guessed.'),
  ...N(['**Your URL pattern** (mode “URL pattern with {page}”) or **your selector** (a pick on the `<span>` inside the link resolves to the link).', '**`rel="next"`** on a link or a `<link>` in the page head.', '**A control that says or means “Next”**: the label (aria-label, title, helper text such as “Next page”), the words in several languages, arrow-only links (› » →), and, inside a pager, a class name such as `pager__item--next`. A control that is switched off (class “disabled”, aria-disabled) means **last page**.', '**The numbered pager**: the current page is the marked one (aria-current, active, current …) or the only number that is not a link; page numbers may be 0-based (“2” links to `?page=1`); the link with the next number is followed; if the current page is the highest number, it is the last page.', '**Only if the page shows no pager at all:** a page number in the address (`?page=4`, `?p=`, `?pg=`, `?pagina=` …) or in the path (`/page/2/`) is increased by one, or an offset (`?start=20`) by the number of entries on the page. This is marked as a guess; a wrong guess is caught by “stop after N pages with nobody new”.', '**In-page buttons** (“Next” that is a button or has no address): clicked, then the list is watched until it changes (single-page apps).']),
  P('When nothing is found, the run does **not** simply say “last page reached”. It says whether a pager exists on the page (“a pager is on the page but no next page could be followed”) or not, and lists what was looked at (“0 × rel=next; 0 “Next”-like links; 1 numbered pager; page 5 is not shown in the pager …”). **Preview** now shows the same: “Next page: … – found by rel=next”, or a warning with the evidence, so a pagination problem is visible before a long run.'),
  H2('7.3 Pager styles covered by tests'),
  T(['Style', 'Result'], [['Drupal pager with `rel="next"`, also three pagers on one page', 'next link of the first pager'], ['`<link rel="next">` only in the head', 'followed'], ['Icon-only button with aria-label “Next page”; arrow-only (›); helper text with hidden decoration; “next” only in a class name', 'followed'], ['Other languages: “Volgende”, “Siguiente »”', 'followed'], ['Numbers only, current page a plain number; first page without a parameter and 0-based links; no marker, page number taken from the address', 'next number'], ['A window of numbers (1 … 9) plus “Next”', 'Next'], ['“Next” disabled; highest number is current', '**stops – never guessed past**'], ['No pager drawn, `?page=4` / `/page/2/` / `?start=20` in the address', 'guessed, marked as a guess'], ['No pager and no number in the address; “Next steps” call-to-action elsewhere on the page; “Next” that is only a script button (`href="#"`)', 'none found – with the evidence listed'], ['Your own selector on the `<span>` inside the link; selector that matches nothing', 'link followed; fallbacks used and the miss reported']], [70, 30]),
  H2('7.4 Page numbers, the page you start on, and similar traps'),
  P('A third report on the same site: the run ended on page 1 with “no pager found on this page ()” – an empty list of evidence. That message can only appear when the **URL pattern** setting computes a next address equal to the current one. The cause was two assumptions: (1) the next number was “first page number + pages read”, i.e. the run was assumed to start on the first page; (2) the site counts from **0** (“Go to page 5” links to `?page=4`, the address of the tab was `?page=1`, which is the second page). With the first number set to 0 and the tab on `?page=1`, the pattern gave `?page=1` again. Now:'),
  ...B(['**The page number is read from the address you are on** with the pattern (query value in any order, or a path part), so any starting page and any numbering base work; “first page number” is only used when the address has no number (a first page without `?page=`).', '**A scrape starts on the first page.** If the tab is on a later page (a Previous / First-page control, `rel="prev"` or the page-1 link exists), the first page is opened first; with a URL pattern the first page is the pattern with the first page number. Preview tells you (“This is not the first page of the list”); the switch is Pagination → “Start from the first page” (on by default).', '**Preview and the run report what they did**, so a wrong assumption is visible: the next address and how it was found, or the list of what was checked.']),
  P('Similar situations on other websites, and what VierCRM does about each:'),
  T(['Situation', 'What happens'], [['Page numbers start at 0 on the site, but the pager labels start at 1', 'The pager link’s own address is followed; patterns read the number from the address – no assumption about 0 or 1'], ['The tab is on page 5 of 20 (or the last page) when you press Start', 'The first page is opened first (Previous / First / number 1 / pattern), then everything is read'], ['Several pagers on one page that share one `?page=` number (this site)', 'One “Next” moves all lists; the first pager’s link is used; shorter lists on later pages are kept'], ['The next page address is the same as the current one (a self-link, a wrongly set pattern)', 'Not followed; the run says so and lists what it looked at'], ['A pager whose links are scripts (`href="#"`) or whose clicks change the list without changing the address (AJAX)', 'The button is clicked and the list is watched until it changes (the address may stay the same)'], ['A pager that appears only after the page has loaded', 'The list wait (6 s) and the pager search both run after the page is ready; Preview can be pressed again after the pager shows'], ['A pager showing a window of numbers (1 … 9 Next)', '“Next” is used; the next number is not required to be visible'], ['“Next” at the last page is disabled, or the highest number is the current page', 'The run stops – nothing is guessed past it'], ['A site that answers beyond its last page with the same or an empty list', '“Stop after N pages with nobody new” ends the run (default 2)'], ['Offset-based pagers (`?start=20`), path-based pagers (`/page/2/`)', 'Derived from the address when the page shows no pager'], ['A page that never finishes loading (trackers)', 'Read as soon as the DOM is ready (section 6.9)'], ['An old copy of the script left in the tab after an update', 'Replaced by the new one on every injection (section 6.10)'], ['Pagers inside an iframe, or letter indexes (A–Z) instead of pages', 'Not supported – use manual selectors, or one scrape per letter with a URL pattern']], [46, 54]),
  P('Controls: **Start / Pause / Resume / Stop** in the Scraper page and the floating control on the scraped page. Progress shows page, people read, new, skipped / duplicates and errors. Pausing waits at the next person, not mid-request.'), pageBreak());

// ---- 8 field mapping
add(H1('8 Field mapping'),
  P('A scraping configuration (`ScrapeConfig`, stored in the `configs` store) contains:'),
  ...B(['**List type** – people, or “companies, products or any other list”; **list detection** – automatic, or a card selector and optional link selector.', '**Auto-detect switches** – name, position, institution (and department), e-mail, phone, biography.', '**Mappings** – for any field: where to read (`card` or `profile`), a CSS selector or `xpath:` expression, what to extract (text, link, attribute, e-mail, phone, text with line breaks), whether all matches are joined, and an optional regular expression (first capture group).', '**Constants** – a value for a field for the whole site (e.g. Institution, Country) used when the page does not say.', '**Profiles** – visit profiles; render JavaScript-only or cross-domain profiles in a background tab; keep the directory page in place.', '**Pagination and limits** (section 7).']),
  H2('8.1 Selecting an element'),
  P('“⌖ Pick” starts the picker in the scraped tab: hovering outlines the element, a click returns the **shortest unique selector**, a **generalised selector** that also matches look-alike elements (other cards), the number of matches and a text sample. Cards use the generalised selector; single values use the unique one; “all matches” mappings use the generalised one. Nested extraction is done with descendant selectors or XPath relative to the card / document.'),
  H2('8.2 Reusable configurations'),
  P('“Save as new…” stores a configuration under a name (for example a university); “Save” updates it; the built-in example is read-only. A new university needs no code change. `samples/scrape-config-example.json` is a complete example with XPath mappings, constants and a Next selector.'),
  ...Img(shot('11-sidepanel.png') || img.architecture, 300, 'Figure 6 – The side panel Records tab, with its base selector and the visible “Open app” button (test data)'), pageBreak());

// ---- 9 database
add(H1('9 Database and bases'),
  H2('9.0 Bases and templates'),
  P('In the interface a table is called a **base**. **＋ Add base** (left menu, Manage bases page, or the Scraper’s “Save to base” selector) opens a dialog: pick a starting point, name it, create it. The template only decides the starting fields, views and duplicate rules; afterwards the base is an ordinary table.'),
  T(['Template', 'Starts with', 'Duplicate rules', 'Automatic research'], [['Contacts', 'Name, first / last name, position, company, country, e-mail, phone, profile URL, about, plus the outreach and scraping fields', 'e-mail, profile URL, name at the same company', 'off'], ['Companies', 'Company, website, industry, size, location, country, e-mail, phone, listing URL, description, plus the outreach and scraping fields', 'e-mail, website, profile URL, name at the same website', 'off'], ['Researchers', 'Contacts fields plus department and the research fields (latest publication, date, URL, DOI, PDF, access, keywords, status)', 'e-mail, profile URL, DOI (off), name at the same institution', 'on'], ['Blank', 'Name, notes, website, source URL, scraping date and status', 'name', 'off']], [16, 44, 26, 14]),
  P('**Research fields are an add-on.** Manage bases (or the field manager’s “✦ Add research fields”) adds the research fields to any base that has a name field; they are wired to that base’s own name, institution and profile-URL fields and the base is switched to automatic research. Fields you made yourself are not duplicated (matched by key and by name). Adding them again changes nothing.'),
  P('**Upgrading from 0.1.0.** The first start of 0.2.0 renames “Research Contacts” to “Researchers”, adds the keys to its fields, creates Contacts and Companies, adds the company e-mail template and the “any list” scraping configuration, and switches automatic research on for Researchers. Records, field ids, views, automations and files are untouched (covered by a unit test that builds a 0.1.0 database and upgrades it).'),
  ...Img(shot('12-add-base.png') || img.architecture, 560, 'Figure 7 – The “Add a base” dialog'),
  ...Img(shot('14-manage-bases.png') || img.architecture, 560, 'Figure 8 – Manage bases: how to add one, rename, delete, research switch or add-on, duplicate rules'),
  H2('9.1 Model'),
  P('Workspace → Database → Base (table) → Fields / Records / Views. Records store cells keyed by field id, so renaming a field never touches data. Each record also has `meta`: scrape information, stored publications per research field, pending author matches, lookup errors, e-mail log ids and the automation origin tag.'),
  H2('9.2 IndexedDB stores'),
  T(['Store', 'Holds'], [['workspaces · databases · tables', 'Structure'], ['fields · views', 'Per-table schema and saved views (index `tableId`)'], ['records', 'People / rows (index `tableId`)'], ['configs', 'Scraping configurations'], ['automations · runs · pending', 'Automations, their history, paused (Wait) runs'], ['templates · emailLog', 'E-mail templates and every send / test'], ['files', 'Attachment blobs (PDFs)'], ['kv', 'Settings, duplicate rules, last scrape, suppression list, repeat-prevention keys …']], [34, 66]),
  H2('9.3 Field types'),
  T(['Type', 'Notes'], [['Text, Long text, Email, Phone, URL, Number, Date, Checkbox', 'Edited inline; e-mail lower-cased; URLs and e-mail rendered as links.'], ['Single select, Multiple select', 'Options per field; multiple select is edited as a comma list.'], ['Formula', 'Computed on read (section 11); errors shown as #ERROR with the message.'], ['Created time, Last modified time', 'Computed from the record.'], ['Attachment', 'PDFs with title, year, venue, DOI, source, access; download and open buttons.'], ['Scraping status · Email status · Publication status', 'Select-like fields written by the scraper, the e-mail service and the research module.']], [38, 62]),
  P('Fields can be created, renamed, retyped, reordered, hidden and deleted (the primary field cannot be deleted). The Researchers template has 33 fields including every field in the brief; each field also has a **key** that names what it means, which is how the rest of the program finds it in any base.'),
  H2('9.4 Duplicate detection'),
  P('Rules depend on the template (section 9.0). For Researchers they default to: same e-mail; same profile URL (normalised: no `www`, no trailing slash); same publication DOI (off); same name at the same institution **unless** both records have an e-mail or profile URL and they differ. Matching ignores case, accents and punctuation. An index makes each check O(1) so thousands of people scrape quickly. A duplicate only fills empty cells of the existing record. CSV import uses the same rules.'),
  H2('9.5 CSV and backups'),
  ...B(['**Import**: any delimiter (`,` `;` tab), BOM, quoted line breaks; header-to-field mapping you can correct; duplicates skipped; automations do not run for imported rows.', '**Export**: UTF-8 with BOM for Excel; cells starting with `= + - @` get a leading apostrophe so spreadsheets never run them as formulas (import removes exactly that).', '**Backup**: one JSON file with every store; PDFs are base64-embedded; restore merges or replaces. API keys are **not** included.']),
  H2('9.6 Preparing for cloud sync'),
  P('Every record, field and view carries `createdAt` / `updatedAt`, ids are random and stable, and all writes go through `core/store.ts`, which already publishes change events. A sync layer can subscribe to those events and replicate by `updatedAt` per store. Nothing of this is implemented.'), pageBreak());

// ---- 10 views
add(H1('10 Views'),
  P('A view stores a filter (AND / OR / NOT groups, nested up to three levels), sorts, hidden fields and a name. Filter and sort edits apply immediately and are saved in the background. Operators follow the field type: text (contains, is, is empty …), number (>, ≥, <, ≤, is), date (before, after, is), checkbox, select, attachment (empty / not empty). `today` is accepted as a date.'),
  P('The views below are the Researchers set; Contacts and Companies get the ones that make sense for their fields (all records, recently scraped, missing e-mail, ready for outreach, e-mail sent / opened, follow-up, failed scraping), and the publication views appear when research fields are added.'),
  T(['Default view', 'Rule'], [['All records', 'no filter'], ['Recently Scraped', 'Scraping Date not empty, newest first'], ['Missing Email', 'Full Name not empty AND Email empty'], ['Ready for Outreach', 'Email, Position, Institution not empty AND Outreach Status = Not Contacted'], ['Missing Publication', 'Full Name not empty AND Latest Publication empty'], ['Publication Found', 'Latest Publication not empty'], ['PDF Available', 'Publication File not empty'], ['Email Sent', 'Email Sent checked'], ['Email Opened', 'Email Opened checked'], ['Follow-Up Required', 'Email Sent AND Outreach Status = Follow-up needed AND not clicked'], ['Failed Scraping', 'Scraping Status = Failed']], [30, 70]),
  P('The “Ready for Research” example from the brief (Full Name not empty AND Latest Publication empty) is built in the browser test through the UI.'),
  ...(shot('03-views-filter.png') ? Img(shot('03-views-filter.png'), 560, 'Figure 9 – Building a view (filter panel)') : []), pageBreak());

// ---- 11 formulas
add(H1('11 Formula system'),
  H2('11.1 Syntax'),
  Code(['expression  := comparison', 'comparison  := concat ( ("=" | "!=" | "<>" | "<" | ">" | "<=" | ">=") concat )*', 'concat      := additive ( "&" additive )*', 'additive    := multiplicative ( ("+" | "-") multiplicative )*', 'multiplicative := unary ( ("*" | "/") unary )*', 'unary       := "-" unary | primary', 'primary     := NUMBER | "text" | \'text\' | {Field Name} | TRUE | FALSE | NAME "(" [expression ("," expression)*] ")" | "(" expression ")"'].join('\n')),
  H2('11.2 Functions'),
  T(['Function', 'Result'], [['`IF(test, then, [else])`', 'Lazy: only the chosen branch is evaluated'], ['`AND` `OR` `NOT`', 'Booleans'], ['`CONCATENATE` `CONCAT`', 'Join text'], ['`LOWER` `UPPER` `TRIM`', 'Case, whitespace'], ['`LEFT` `RIGHT` `MID` `LEN`', 'Substrings and length'], ['`FIND(needle, text, [start])`', '1-based position, 0 when absent'], ['`SUBSTITUTE(text, old, new)`', 'Replace all'], ['`IS_EMPTY` `IS_NOT_EMPTY`', 'Empty text / list / null'], ['`TODAY` `NOW`', 'Dates'], ['`ROUND` `ABS` `VALUE` `YEAR` `DATETIME_DIFF_DAYS` `BLANK`', 'Extras beyond the brief']], [42, 58]),
  H2('11.3 Safety'),
  P('Formulas are parsed into a tree and interpreted; only the functions above exist. `eval`, `Function` and property access are not available, so a formula such as `constructor.constructor("…")()` is a parse error. Errors never throw: the field shows #ERROR with a message such as “Unknown field {X}”, “Division by zero” or “Circular reference between formulas”. The field editor shows a live preview on the first record.'),
  H2('11.4 Templates'),
  Code(['Hi {First Name | fallback: Researcher},', 'I noticed your research at {Institution}.', '[[I was particularly interested in your work on {Latest Research}.]]'].join('\n')),
  P('`{Field}` is the field’s text; `{Field | fallback: text}` is used when empty; `[[ … ]]` is dropped together with its line when any field inside is empty; unknown fields are reported, never filled in. The preview shows which fallbacks were used and which values were empty.'), pageBreak());

// ---- 12 automation
add(H1('12 Automation engine'), ...Img(img['automation-flow'], 640, 'Figure 10 – Trigger, guards, conditions, actions'),
  H2('12.1 Triggers'),
  T(['Trigger', 'Fires when'], [['Record created / updated', 'A record is created, or any cell changes'], ['Field becomes non-empty / empty / changes', 'The watched field goes from empty to filled / filled to empty / changes value'], ['Record enters a view', 'It did not match the view before the change and does now'], ['Scraping completed', 'The scraper has saved or filled a record'], ['Publication found', 'A research run stored a publication'], ['Scheduled', 'Every N minutes, for records matching the conditions (at most 25 per run by default)'], ['Manual', 'You run it (“Test on 5 records”, “Run on up to 25”)']], [34, 66]),
  H2('12.2 Conditions and actions'),
  P('Conditions are the same AND / OR / NOT groups as views. Actions run in order and stop at the first error:'),
  T(['Action', 'Behaviour'], [['Send e-mail', 'Template, provider, sender, recipient field → section 15 guards'], ['Update field', 'Text with `{Field}` placeholders, or `=FORMULA`; calculated fields are refused'], ['Change status', 'Sets a select / status field'], ['Create record', 'In this or another table, with templated values'], ['Run publication lookup', 'All research fields, or one'], ['Download authorised PDF', 'Runs the PDF field (lawful sources only)'], ['Update publication metadata', 'Refreshes derived fields from the stored publication'], ['Wait', 'Stores a pending job; the one-minute alarm continues the run'], ['Execute another automation', 'Refused if it would loop back']], [34, 66]),
  H2('12.3 Loop and duplicate prevention'),
  ...B(['Every write an automation makes is tagged `{ automationId, chain, depth }`. A change whose chain already contains automation A can never trigger A; nothing runs deeper than 4 levels. The browser test builds A (changes Phone when Notes changes) and B (changes Notes when Phone changes): each runs exactly once.', 'One-shot triggers remember a key per record and value (“Email became non-empty with *this* value”), so editing and re-editing does not re-run it; re-entering a different value does.', 'E-mail has its own duplicate rule: the same template is never sent twice to the same record.']),
  H2('12.4 Test mode, activation, history'),
  P('New automations are **off** and in **test mode**. In test mode every step is described (“would set Notes to …”, “TEST – would send … Nothing was sent.”) and nothing is written, sent or downloaded. Turning on an automation that sends e-mail with test mode off requires a confirmation. Each run stores trigger, steps with status (ok, test, skipped, error), chain and depth; failed runs have a **Retry** button.'),
  ...(shot('09-automations.png') ? Img(shot('09-automations.png'), 560, 'Figure 11 – Automation builder') : []), pageBreak());

// ---- 13 publication discovery
add(H1('13 Publication discovery'), ...Img(img['research-chain'], 640, 'Figure 12 – From a name to a publication and a PDF'),
  H2('13.1 Sources'),
  T(['Source', 'Kind', 'How it is used'], [['OpenAlex', 'Author-based', '`/authors?search=` → candidates with institutions and topics → `/works?filter=author.id:…&sort=publication_date:desc` (errata, retractions, paratext skipped); abstract from the inverted index; open-access status and PDF location.'], ['Semantic Scholar', 'Author-based', 'Author search, then the author’s papers sorted locally; `openAccessPdf`. Optional API key.'], ['Crossref', 'Publication-based', 'Best-matching works by author (+ affiliation), then **each hit’s author list is checked**; the newest verified one wins. (Sorting by date was tried first and returned namesakes – see 13.5.)'], ['PubMed', 'Publication-based', '`[Author]` (+ `[Affiliation]`) search; only weak evidence because PubMed has no author ids.'], ['Google Scholar, ResearchGate', 'Publication-based, **through a tab in your browser**', 'One page per 8 seconds, your own session; the page parser stops at “unusual traffic” / security checks and says so. Name-only evidence.'], ['Unpaywall, Europe PMC, arXiv, repositories / publisher pages', 'Full text', 'Section 14.']], [22, 22, 56]),
  P('Searches can be restricted by year range and by words the title / abstract / keywords must contain, per field or in the Research Finder page. The author-search page also accepts a name and institution without any record.'),
  H2('13.2 Who is this author?'),
  T(['Evidence', 'Score'], [['Full name equal (any order, accents / honorifics ignored)', '+0.50'], ['Same surname and first name (middle names ignored)', '+0.45'], ['Same surname, first-name prefix (“Jon” / “Jonathan”)', '+0.40'], ['Same surname and initial', '+0.35'], ['Different first name', '0 (rejected)'], ['Same institution (words like “University of” ignored)', '+0.30'], ['Similar institution (≥ half the words)', '+0.20'], ['The profile URL / identifiers on the page contain this author’s ORCID or source id', '+0.60'], ['Overlapping research topics', 'up to +0.10']], [74, 26]),
  P('A candidate is chosen automatically only when its confidence is **≥ 0.75** and it leads the runner-up by **≥ 0.20** (both configurable). Name alone (0.50) can never pass. Otherwise the user sees every plausible candidate with the reasons and picks one; **nothing is fetched or filled** until then. The stored publication keeps the author match and its reasons (“chosen by you” when you decide).'),
  ...(shot('05-match-chooser.png') ? Img(shot('05-match-chooser.png'), 560, 'Figure 13 – Two researchers named Wei Zhang at the same institution: the user chooses (test data)') : []),
  H2('13.3 Research fields and dependencies'),
  P('A lookup field has a **kind**: search (finds the publication), derive (DOI, year, date, URL, authors, venue, abstract, access, keywords), pdf, abstract (stored or fetched by DOI), keywords (from the paper). `dependsOn` lists extra fields that must be non-empty. `core/deps.ts` builds the graph, orders it upstream-first and reports cycles and misconfiguration; the Dependencies tab of the field manager draws the order. A run follows these rules:'),
  ...B(['a field with a value is left alone (unless “Redo (overwrite)”); your typed or scraped values are never replaced;', 'if an upstream field is empty, the field is skipped and the log says which one (“skipped – “Latest Publication” is empty”);', 'a search that finds nothing sets Publication Status = Not found and stores the reasons; an ambiguous one sets Needs match;', 'the stored publication is kept in the record so derived fields never need the network.']),
  ...(shot('06-field-dependencies.png') ? Img(shot('06-field-dependencies.png'), 560, 'Figure 14 – Field dependencies and run order (a custom “Publication Abstract” field added in the UI)') : []),
  H2('13.4 Configurable by the user'),
  P('Everything above is configuration, not code: a field is created in the UI with its sources, name / institution / profile fields, year range and keyword filter, or as a derived / PDF / abstract / keywords field reading another. The default table ships the chain Full Name → Latest Publication → Publication Date / URL / DOI / Access / Latest Research / Research Keywords / Publication File.'),
  H2('13.5 Automatic research'),
  P('**What it does.** In a base that has a search field (“Latest Publication”) and has “Find research automatically” switched on, every record whose name field has at least three characters and whose Latest Publication is empty is looked up – whether it was scraped, imported or typed. The lookup is the normal chain (section 13.3) **without the PDF step**: details only; PDFs are fetched on request or through an automation, so a long list never fills the browser with downloads. Nothing is guessed: an ambiguous person waits in **Needs match** for you.'),
  T(['Situation', 'What happens'], [['Publication found', 'Fields filled, outcome “found”; the “Publication found” trigger fires'], ['Nothing found (or only errors that mean “no result”)', 'Marked “none”; tried again after 7 days'], ['A request failed (network, rate limit)', 'Marked “error”; tried again after 1 hour'], ['Several people could match', 'Marked “needs match”; never retried until you choose'], ['Record already has a publication, or has a pending match', 'Not touched']], [44, 56]),
  P('**When.** The background worker looks at a base only after one of its records changed (and once after every browser start), researches **five records per minute**, newest first, and stops when none are left; it works only while the browser is open. Separately, opening a base researches the records **in the view you are looking at** in batches of five (a chip in the header says “researching automatically · N waiting”). The switch is per base (Manage bases or Research Finder). The tests cover the candidate rules, the retry intervals, the five-record limit, that no PDF is downloaded, and that a base with the switch off is left alone.'),
  ...(shot('16-auto-research.png') ? Img(shot('16-auto-research.png'), 560, 'Figure 15 – A base researching automatically (test data; the fake research service answers)') : []),
  ...(shot('15-research-finder.png') ? Img(shot('15-research-finder.png'), 560, 'Figure 16 – Research Finder: plain-language explanation, base selector and progress') : []),
  H2('13.6 Live verification of the public APIs'),
  P(`On ${when} the real adapters were run against the real public services, read-only, with no API keys and none of your details (a well-known public author was searched; \`scripts/live-check.ts\`):`),
  T(['Service', 'Result'], [['OpenAlex authors', 'Candidates returned and scored; the right author chosen automatically (80 %).'], ['OpenAlex latest work', 'Returned the author’s newest item with date, DOI and open-access status.'], ['Crossref', 'After the fix in 13.1 returned the same newest item. The first version sorted by date and returned namesakes – found by this check, fixed, covered by the author-list verification.'], ['PubMed', 'Hits returned and parsed.'], ['Semantic Scholar', 'HTTP 429 without an API key (reported cleanly after retries). Use a key for regular use.'], ['OpenAlex by DOI', 'Record parsed; some publishers’ abstracts are withheld by OpenAlex, in which case Crossref / Semantic Scholar are tried next.'], ['Full-text finder (arXiv paper)', 'A real 2.1 MB PDF was downloaded and passed the `%PDF-` check.'], ['Unpaywall, Brevo, Gmail', 'Not called live.']], [30, 70]), pageBreak());

// ---- 14 attachments
add(H1('14 Publication attachment management'),
  H2('14.1 The workflow'),
  ...N(['Publication found (section 13) → its DOI, URLs and any PDF link are stored.', 'Candidates, in order: the source’s own PDF link; Unpaywall (needs your e-mail); OpenAlex locations; Europe PMC open-access full-text links; arXiv (DOI `10.48550/arxiv.*`); the publication’s landing page `citation_pdf_url` tag.', 'Each candidate is downloaded and **validated**: HTTP 200, size below the limit (default 40 MB), and the bytes must contain `%PDF-`. Login pages, HTML landing pages and 403 / 401 responses are rejected with the reason logged.', 'The first valid PDF is stored in the `files` store and attached with title, year, venue, DOI, source URL and access label; Publication Status = PDF attached.', 'If none is valid: the field shows **Full text unavailable**, the metadata and links stay, and the log lists what was tried.']),
  H2('14.2 Lawful sources only'),
  Note('VierCRM does **not** use Sci-Hub, LibGen or similar sites, and it never works around a paywall, login or CAPTCHA. Open-access copies, repository copies, PDFs you attach yourself, and – only if you switch on “Use my browser session” – publisher PDFs your own institutional subscription already lets you read (the request is made with your cookies exactly as your browser would). If a copyright holder has not made the paper available, the answer is “Full text unavailable”.', 'warn'),
  H2('14.3 In the interface'),
  P('The attachment cell and record panel show a card with a document icon, file name (or paper title), year, venue, size and access label, a **download** button and an **open** button. The unavailable state links to the publication page. “Attach a PDF I have” stores your own file. Backups include the PDFs.'),
  ...(shot('04-record-publication.png') ? Img(shot('04-record-publication.png'), 560, 'Figure 17 – Publication card and PDF attachment (fixture data)') : []), pageBreak());

// ---- 15–17 email
add(H1('15 Email integration'),
  H2('15.1 Templates and personalisation'),
  P('Templates (subject and body) use the syntax in section 11.4. The Email page previews the exact subject and text for any contact, the recipient and sender, fallbacks used and empty fields. An opt-out footer from Settings is appended to every message. Test sends: “Test send” (nothing leaves the computer; logged as a test) and “Send ONE real test to my own address” (explicit confirmation, does not mark the contact as contacted).'),
  H2('15.2 The send service’s guard rails (`email/service.ts`)'),
  T(['#', 'Guard', 'Outcome'], [['1', 'Valid recipient address', 'skipped with the reason'], ['2', 'Test mode (automation test mode, or not enabled)', 'rendered and logged as a test; nothing sent'], ['3', 'Global “Allow sending” (off by default)', 'skipped'], ['4', 'Outreach Status = Do not contact / Not interested', 'skipped'], ['5', 'Email Status Bounced / Unsubscribed, or address on the suppression list', 'skipped'], ['6', 'This template already sent to this record', 'skipped'], ['7', 'Daily cap (default 40) and minimum gap (default 30 s)', 'skipped'], ['8', 'Brevo: sender must be an **active** Brevo sender (checked, cached 10 min)', 'error with instructions'], ['9', 'Gmail: the connected account must be allowed to send as the address', 'error with instructions']], [6, 62, 32]),
  P('A successful send writes an e-mail log row and updates the contact: Email Sent, Email Status = Sent, Outreach Status = Contacted (if it was Not Contacted). Newly scraped contacts are never e-mailed automatically; only an automation you activated, or a manual run, sends.'),
  H2('15.3 Providers'),
  T(['', 'Brevo', 'Gmail'], [['Sending', 'Transactional API (`POST /v3/smtp/email`)', '`users.messages.send` with a raw RFC 822 message'], ['Sender', 'Must be an active Brevo sender (e.g. `info@vierapparatus.com`)', 'Primary address or a verified **Send As** alias of the connected account'], ['Analytics', 'Yes – section 16', '**None**'], ['Credentials', 'API key in `chrome.storage.local`', 'Your Google OAuth client id; access token in `chrome.storage.local`'], ['Multiple accounts', 'One key', 'Several accounts are supported; the one that can send as the chosen address is used'], ['Status', 'Fake-tested; not verified with a real key', 'Unit-tested pieces; not verified with a real account']], [18, 41, 41]),
  Note('Gmail “Send As” lets `info@vierapparatus.com` send through the Gmail account `satrio666sto@gmail.com`, but Gmail provides no open or click tracking. The two are therefore kept apart: choose Brevo when you want analytics.', 'warn'),
  ...(shot('07-email.png') ? Img(shot('07-email.png'), 560, 'Figure 18 – Template, preview and sender (test data)') : []),
  H1('16 Brevo analytics'),
  P('Two ways to get events, both implemented:'),
  ...B(['**Polling (default, needs no server):** `email:sync` asks Brevo’s `/smtp/statistics/events` for every Brevo message sent in the last 30 days. It runs from the Analytics page and on the one-minute alarm every `brevoSyncMinutes` (default 15) while Chrome is open.', '**Webhook (near real time, optional):** Brevo calls a public HTTPS URL. A browser extension cannot listen for incoming connections, so `backend/webhook-server.mjs` receives the events (secret in the URL, since Brevo cannot send custom headers) and the extension fetches them with a bearer token. This is the reason a backend exists at all.']),
  T(['Brevo event', 'Effect'], [['delivered', 'log; status Delivered'], ['opened / loadedByProxy', 'Email Opened ✓, Last Opened = date, status Opened'], ['click', 'Email Clicked ✓, Last Clicked, status Clicked (and opened)'], ['soft / hard bounce, invalid, blocked', 'status Bounced; address suppressed'], ['unsubscribed, spam', 'status Unsubscribed; Outreach Status = Do not contact; address suppressed']], [32, 68]),
  P('The Analytics page shows sent, delivered, unique opens, clicks, bounces, unsubscribes, failures and the rates, plus the message log.'),
  Note('**Open rates are imperfect.** Apple Mail Privacy Protection and some security scanners load the tracking image automatically (so machines are counted as opens), and readers who block images are never counted. Treat opens as a rough signal and clicks and replies as the real one. Tracking itself is switched on in the Brevo account, not by VierCRM.', 'warn'),
  ...(shot('08-analytics.png') ? Img(shot('08-analytics.png'), 560, 'Figure 19 – Analytics (the single message sent to the local fake provider in the test)') : []),
  H1('17 Gmail integration'),
  ...B(['**Setup:** create a Google Cloud OAuth client (type *Web application*), enable the Gmail API, add the redirect URI shown in Settings (`https://<extension-id>.chromiumapp.org/`), paste the client id.', '**Sign-in:** `chrome.identity.launchWebAuthFlow` with the implicit flow; scopes `gmail.send`, `gmail.settings.basic` (to list Send As identities) and `userinfo.email`. The access token (about 1 hour) is stored in `chrome.storage.local`; when it expires the account must be reconnected.', '**Send As:** `settings/sendAs` is read; an alias counts only when its verification status is accepted.', '**Sending:** a multipart/alternative UTF-8 message (text and HTML) is built and posted to `messages/send`.', '**Not covered:** reading replies, bounce detection, analytics. Note that Google restricts the `gmail.send` scope for published apps; for personal use the OAuth consent screen can stay in testing mode.']),
  Note('The Gmail path is written and its message building and rules are unit-tested, but it has **not** been run against a real Google account (that needs your credentials).', 'warn'), pageBreak());

// ---- 18 security
add(H1('18 Security'),
  T(['Concern', 'Measure'], [['API keys and tokens', 'Only in `chrome.storage.local` (extension-private); never in IndexedDB, backups, CSV, logs, page code or the UI (shown masked, e.g. ••••1234). The browser test checks that the key does not appear in the Settings page markup.'], ['Where keys are used', 'Only in the service worker; pages never call Brevo / Gmail / research APIs.'], ['Code injection', 'No `eval` / `Function`; formulas are interpreted from a tree; CSP `script-src \'self\'`; no remote scripts; React escapes output; templates are escaped before becoming HTML.'], ['Spreadsheet injection', 'CSV export prefixes cells starting with `= + - @`.'], ['Broad site access', 'Optional, requested at use, revocable; not requested at install.'], ['Webhook backend', 'Binds to 127.0.0.1; secret path for Brevo and bearer token for the extension (timing-safe compare); body-size limit; stores only event type, e-mail, message id, date, link.'], ['Accidental e-mail', 'Section 15.2 plus off-by-default automations, test mode, activation confirmation.'], ['Scraping etiquette', 'Delays, caps, no CAPTCHA / login bypass, stops at security checks, Scholar / ResearchGate at one page per 8 seconds in your own session.'], ['Data location', 'Everything stays in the browser profile; no analytics, no telemetry, no VierApparatus server.']], [24, 76]),
  H2('18.1 Legal and ethical notes'),
  ...B(['**Scraping** may be restricted by a site’s terms; you are responsible for respecting them and for data-protection law (GDPR etc.) when collecting personal data of researchers.', '**Cold e-mail** is regulated (GDPR / ePrivacy, CAN-SPAM, others). You need a lawful basis, an honest sender identity, a working opt-out and a physical address in the footer. VierCRM honours unsubscribes and bounces but cannot make a campaign lawful.', '**Copyright:** only open-access or otherwise lawfully accessible full texts are fetched.']), pageBreak());

// ---- 19–21
add(H1('19 Installation'),
  ...N(['Install Node.js 20 or newer and Chrome 116 or newer.', 'In the project folder run `npm install`, then `npm run build` (creates `dist/`).', 'Open `chrome://extensions`, enable **Developer mode**, choose **Load unpacked** and select the `dist` folder.', 'Pin the VierCRM icon; click it to open the side panel. Use **Open app ↗** (white button, top right of the panel) for the full app.', 'After changing the code run `npm run build` again and press reload on the extension card.', 'Optional: `node backend/webhook-server.mjs` for webhooks (section 16).']),
  H1('20 Configuration'),
  T(['Where', 'What to set'], [['Settings → Website access', 'Press “Allow VierCRM to read the sites I scrape” once.'], ['Settings → Publication research', 'Your e-mail for Unpaywall (optional but recommended); thresholds; “institutional access”; optional Semantic Scholar key.'], ['Settings → E-mail → Brevo', 'API key (Brevo → SMTP & API); verify `info@vierapparatus.com` is an active sender (Email page → “Verify sender with Brevo”); enable open / click tracking in Brevo.'], ['Settings → E-mail → Gmail', 'OAuth client id; add the shown redirect URI in Google Cloud; Connect Gmail.'], ['Settings → E-mail', 'Default provider, sender and name, daily cap, minimum gap, opt-out footer, and — last — **Allow sending**.'], ['Settings → Webhook backend', 'URL and token printed by the backend (optional).'], ['Scraper', 'Choose **Save to base**, the configuration, Preview, Start.'], ['Manage bases', 'Add bases, switch automatic research, add research fields, duplicate rules.']], [30, 70]),
  H1('21 Troubleshooting'),
  T(['Symptom', 'Cause and remedy'], [['Preview finds 0 people', 'The list had not loaded, or the markup is unusual. Scroll the list into view and retry; otherwise Edit configuration → switch off automatic detection and ⌖ Pick a card.'], ['“VierCRM needs permission to read this website”', 'Grant it in the prompt (Settings → Website access).'], ['A profile has no e-mail', 'The page does not state one, only a generic role mailbox, or it is drawn as an image. By design nothing is guessed. Add a mapping with a selector if it exists in the page.'], ['Run stops with “next page did not load”', 'Slow site or blocked request; raise the delay and retry. A CAPTCHA or login page ends the run – solve it yourself and start again.'], ['“Needs match” on a contact', 'More than one author fits. Open the record and choose; adding Institution or an ORCID / profile URL makes future matches automatic.'], ['“Full text unavailable”', 'No open-access copy exists (or Unpaywall is not set up). Open the publication page, or attach a PDF you are allowed to use.'], ['Scholar / ResearchGate gives an error', 'A human check was shown. Open the site, solve it, retry later. Heavy use will be blocked by those sites.'], ['Google Maps: “no Maps results found”', 'The tab shows no result list – a consent page, a sign-in, a CAPTCHA, or the results had not loaded. Open a search, wait until the places are listed in the left panel, press Preview, then Start.'], ['Google Maps: only about 120 places', 'Google Maps lists at most that many for one search. Add more searches (the same words plus a city or district) under Edit configuration → More searches.'], ['Google Maps: phone, address or website empty for every place', 'Google changed its markup. Press Preview and look at the counts; send the HTML of one result card so the reader can be adjusted (section 26.6).'], ['HTTP 429 from Semantic Scholar', 'Add an API key or retry later.'], ['Brevo: “not a sender in this account” / 401', 'Add and verify the sender in Brevo; re-enter the API key.'], ['E-mail “skipped – Sending is switched off”', 'Settings → Allow sending (and the automation must be on and out of test mode).'], ['Scrape ended when Chrome closed', 'Runs are not resumed after a restart; start again – de-duplication prevents repeats.'], ['A company list finds only some entries, or none', 'Choose the configuration “Companies / any listing”, or set the list type to “companies, products or any other list”. If the site draws the list with JavaScript, wait for it to appear before Preview. Otherwise pick one card with ⌖ (manual selectors).'], ['A field I added is not filled by the scraper', 'It is filled when the page shows a “Label: value” row (or a definition list / table row) whose label equals the field’s name. Rename the field to the label, or add a mapping with a selector.'], ['Nothing researches automatically', 'The base needs research fields and the “Find research automatically” switch (Manage bases); only records with a name and an empty Latest Publication qualify; the worker does about five per minute and only while Chrome is open; a person not found is retried after 7 days.'], ['The URL pattern setting stops at once, or reads the same page again', 'Fixed in 0.2.4: the page number is read from the address you are on. Check that the pattern has {page} exactly where the number goes (https://site/people?page={page}) and that “first page number” is 0 or 1 as the site counts; start with Preview.'], ['The run stops on page 1 and says “a pager is on the page but no next page could be followed” (or “no pager found”)', 'Press **Preview** on the list page: it shows the next page it would follow, or lists what it looked at. If your pager is a script button, set Pagination → “Next link or button” and pick it with ⌖; if the address has a page number (?page=, /page/2/) and no pager is drawn, VierCRM derives the next page itself. Reload the page after updating the extension so the newest script runs. Start on the FIRST page of the list.'], ['The scrape reads page 1 and stops (“next page did not load”)', 'Fixed in 0.2.2: heavy sites that never finish loading all their images and trackers are now read as soon as the list is on screen. Start on the FIRST page of the list (a scrape only moves forward), and leave “How does the list continue?” on “Detect automatically” unless it really fails.'], ['Preview finds 0 people although the list is plainly visible', 'Usually a rule that treats the whole page as a banner or menu (fixed in 0.2.1 for classes on <body>), or a list drawn by JavaScript after the page loads: scroll the list into view, wait, press Preview again; otherwise use ⌖ Pick a card.'], ['The e-mail is missing for people whose profile shows an address', 'Some sites assemble the address with a script. VierCRM reads mailto: links, Cloudflare-protected, “[at]”-spelled and base64-in-attribute addresses; if the address appears only after a click or is an image, add a mapping with a selector or leave it empty.'], ['A page shows “This page hit a problem”', 'Press Try again or Reload; details are in the console of the app page.']], [32, 68]), pageBreak());

// ---- 22 limitations
add(H1('22 Known limitations'),
  ...B(['**Not verified with real credentials:** Brevo sending / events, Gmail OAuth and sending, Unpaywall, the webhook behind a real tunnel. They are implemented against the documented APIs and tested with imitations.', '**Google Scholar and ResearchGate** are read from rendered pages; markup, rate limits and blocking on the real sites were not tested, and both sites restrict automated access. Prefer the API-based sources.', '**Scraping is heuristic.** Sites with unusual structure may need manual selectors; sites that need login, show names as images, or forbid automation cannot be handled.', '**Google Maps** is read from structure and text, not from Google’s class names, but it has not been run against the live site (section 26.6); Maps shows about 120 places per search; e-mail addresses come only from the business’s own website.', '**Runs do not survive** closing Chrome or a worker restart.', '**One Brevo / Gmail account at a time** for sending from the UI (Gmail supports several accounts internally).', '**Duplicate rules** can be switched on / off but not created in the UI; **workspaces** cannot be created in the UI; a base cannot be copied or converted from one template to another (add and remove fields instead).', '**Multiple select** fields are edited as comma lists; **attachments** keep one PDF per publication from lookups (several can be added by hand).', '**Open counts** are imperfect (section 16); Gmail has no analytics.', '**Author matching** can still be wrong when a namesake shares the institution and nothing else distinguishes them; this is why close calls are shown to you.', '**The browser test** runs on Chromium with the real extension but cannot click Chrome’s permission prompt or dock the side panel; the test copy of the manifest holds the optional host permissions.', '**Performance:** measured with 20 000 records on one computer (section 25); numbers vary by a factor of about two between runs and machines. Bases with hundreds of thousands of records were not tried; opening a base still reads all its records into memory.', '**Automatic research** handles about five records per minute and only while Chrome is open; a 5 000-record list takes about a day. It sends names (and institutions) to the public research services you have enabled.', '**Apollo and LinkedIn** were not scraped (section 6.8); company-list extraction was tested on a fictional directory only.', '**Fonts:** the app bundles Jost; this Word document specifies Jost for headings and falls back to your system font if it is not installed.']),
  H1('23 Future improvements'),
  ...B(['Resume interrupted scrapes (persist the page state and seen-set).', 'Cloud sync built on the change events and `updatedAt`.', 'Rule editor for duplicate detection; workspace management; per-field validation.', 'Per-repository adapters (DSpace, EPrints, institutional CRIS systems) and ORCID public-API lookup for author identity.', 'Gmail reply and bounce detection; reply tracking in Brevo.', 'Campaign scheduling windows (time zone aware), send throttling per domain, and an unsubscribe landing page.', 'Saved scraping recipes shared as files; a recipe test mode that reports field coverage across a sample of profiles.', 'Bulk selection of several PDFs per publication, supplementary files.', 'Accessibility review of the grid with a screen reader.']), pageBreak());

// ---- 24 visual identity
add(H1('24 Visual identity'),
  P('VierCRM follows the VierApparatus website. The reference was the website project itself (`vierapparatus/src/app/globals.css`, `icon.svg`, `public/brand/vier-black.svg`, the header component), not the colour palette alone.'),
  T(['Website', 'VierCRM'], [['White surfaces, ink text #231F20, brand blue #4570B6, sky #CAEBFB', 'White pages and a light sidebar; sky for the active item, table headers and chips; ink for text'], ['Jost, headings weight 600, slightly tight', 'Jost 400 and 600 (latin subset only); headings 600'], ['Primary button: blue, white text, ink on hover', '`button.primary`'], ['Secondary button: white, 2 px blue border, blue text, sky on hover', 'Every other button'], ['Inputs: 1 px ink at 30 %, 8 px radius, 3 px blue focus ring', 'All inputs, selects and text areas; the focus ring is also used for keyboard focus everywhere'], ['Table headers in sky', 'Grid and table headers'], ['Wordmark logo in the header', 'The website’s `vier-black.svg` at the top of the sidebar and the side panel'], ['`icon.svg` (blue rounded square, white V, pipette)', 'The toolbar and store icons are rendered from a copy of it (`assets/icon.svg` → 16 / 32 / 48 / 128 px)']], [46, 54]),
  H2('24.1 The invisible button'),
  P('The previous version showed an empty white button at the top right of the side panel. Cause: all buttons were declared `color: inherit` and had a white background, and the panel header was dark with white text – so the button text was white on white. Now every button states its own colour (blue on white, white on blue), the header is white like the website’s, and the button reads **Open app ↗**. The browser test measures the button: it has text, a 2 px blue border and a text colour different from its background.'),
  H2('24.2 A font bug found on the way'),
  P('Chrome gives extension pages their own default body font (Segoe UI on Windows), which overrode the Jost set on the root element – so Jost, although bundled, was never used in 0.1.0. `body` now inherits the brand font; the browser test checks the computed font and that the two Jost files are loaded.'),
  ...Img(shot('01-dashboard.png') || img.architecture, 560, 'Figure 20 – Dashboard in the new style (empty install, test run)'), pageBreak());

// ---- 25 performance
const bm = bench ? Object.fromEntries(bench.rows.map(r => [r.metric, r])) : {};
const ms = v => (v == null ? 'n/a' : `${v} ms`); const pct = r => (r && r.before && r.after != null ? `−${Math.round((1 - r.after / r.before) * 100)} %` : '–');
const row = (label, key, note) => [label, ms(bm[key]?.before), ms(bm[key]?.after), pct(bm[key]), note || ''];
add(H1('25 Performance and load speed'),
  P(`**Method.** \`tests/perf/bench.mjs\` loads ${bench ? bench.records.toLocaleString('en') : '20 000'} records into the Researchers base of the real built extension in Chromium and measures, inside the page, how long each action takes (median of several repetitions; the table shows the median of ${bench?.runsAfter ?? 3} complete runs after the changes and one run before). The computer was also doing other work, so figures vary by about a factor of two between runs; the large differences below are far outside that.`),
  T(['Action (20 000 records)', 'Before', 'After', 'Change', 'What changed'], [
    row('Open a base – first rows visible', 'openBase (grid with rows)', 'The first 150 records are read and painted before the full list is read (the header says “loading all records…” meanwhile)'),
    row('A change made in another tab / by the worker appears in the grid', 'another tab edits a cell → grid shows it', 'Only the changed record is fetched and patched in; before, the whole table was reloaded'),
    row('Switch to another view', 'switch view (Missing Email)', 'Row values are cached per record; the filter stops at the first decisive condition'),
    row('Type in the search box', 'search “anna fixture” (keystrokes)', 'Each record’s searchable text is built once and cached; a keystroke is one \`includes\` per record'),
    ['Sort by a column', 'n/a (see note)', ms(bm['sort by Full Name (header click)']?.after), '–', 'Sort keys computed once per row, one shared collator'],
    row('Dashboard: counts visible', 'dashboard (all bases counted)', 'Counts come from the index; the statistics that need every record fill in afterwards'),
    row('200 changes arrive while a grid is open: main thread blocked', 'burstMainThreadBlockedMs', 'Patching instead of reloading'),
    [ 'JavaScript heap with the base open', bm.heapMB?.before ? `${bm.heapMB.before} MB` : 'n/a', bm.heapMB?.after ? `${bm.heapMB.after} MB` : 'n/a', bm.heapMB ? pct(bm.heapMB) : '–', 'Rows keep their identity; no duplicate copies on refresh'],
  ], [26, 10, 10, 9, 45]),
  Note('The “before” run is the previous build of the same program with the lazy-loaded pages and font changes already in. The sort time was not measured correctly in that run (the benchmark’s condition was trivially true), so no comparison is claimed for sorting.', 'info'),
  H2('25.1 Load speed of the shell'),
  T(['', 'Before this revision', 'Now'], [['JavaScript read before the app shows (full app)', 'about 340 KB (one 82 KB entry plus a 257 KB shared chunk; every page included)', `${jsFirst} KB (entry plus shared chunks; every page is loaded when visited)`], ['JavaScript read before the side panel shows', 'about 340 KB', `${jsSide} KB`], ['Font files bundled', '18 (three subsets × three weights × two formats)', `${fontFiles.length} (Latin only, weights 400 and 600)`], ['Entry file', '82 KB, all pages inside', 'a few KB; Dashboard, Bases, Scraper, Research, Automations, E-mail, Settings and the table view are separate chunks']], [34, 36, 30]),
  P('The sizes “now” are read from the `dist` folder when this document is built; the “before” values were recorded from the previous build.'),
  H2('25.2 What was done, in order of effect'),
  ...N(['**Cached row values and search text** per record object (`computeRecordCached`, `searchBlob`): changing a view, the filter, the sort or the search never recomputes unchanged records. Formulas keep the old, slower path; bases without a formula field use a fast path with no name map and no closures.', '**Patching instead of reloading**: the change broadcast now names the record; open pages fetch just that record and swap it in (a burst of more than 600 changes falls back to one reload). Editing a cell, adding a record, deleting a selection, creating a view and the research of the visible records no longer reload the whole table.', '**Progressive loading** of a base: head first (150 records), then the rest.', '**Sorting** with keys computed once per row and a single `Intl.Collator`; **filters** stop at the first decisive condition.', '**Counts from the index** (`IDBIndex.count`) instead of loading every record to count it.', '**Lazy pages and a separate React chunk**; **latin-only fonts**; **no dependency on a browser for a normal build** (icons are committed).', '**Automatic research** runs only for bases that changed, in batches of five, details only.']),
  H2('25.3 What was not changed'),
  ...B(['Opening a base still reads all its records into memory; at several hundred thousand records this would need a paged store.', 'The dashboard statistics (with e-mail, with publication …) still read every record, after the page has appeared.', 'Scraping speed is limited on purpose by the delays you configure, not by the program.']), pageBreak());


// ---- 26 Google Maps
add(H1('26 Google Maps scraping'),
  P('VierCRM can read a **Google Maps search** from the tab you have open – no Google API, no key, no extra account. It reads the page you are looking at, the way the directory scraper reads a staff list, and then adds contact details from each business’s own website, because Maps itself never shows an e-mail address. Typical use: search “freight forwarder Surabaya” or “kos putri Malang”, press Start, and get every place with its phone, website and e-mail in a base.'),
  H2('26.1 How a run goes'),
  ...N(['You search on Google Maps and wait until the places are listed. The Scraper recognises the page (`isMapsUrl`: google.<country>/maps) and switches to the built-in configuration “Google Maps results (places)”; a Preview shows the places loaded so far with how many have a phone, an address and a website.', 'Start: the background worker (`crawlMapsSearches`) injects the content script, which waits for the scrolling result list (`role="feed"`) and scrolls it (`loadFeed`) until the list ends, stops growing for two rounds, or the limit is reached. Maps adds about 20 places per scroll.', 'Each entry is read from its card (`parseCard`): name, rating, review count, category, address, phone, website, coordinates and the link to the place.', 'When the card shows no phone number or no address (setting “Open a place’s own page”), the place is opened in a background tab – the same mechanism as profile pages – and read there (`readPlace`: address, phone, website, category, plus code, weekly hours, rating).', 'The business website (Google’s redirect unwrapped, tracking parameters removed) is fetched by the service worker (`siteContacts`): the home page first, then at most two contact pages, and only while no e-mail address has been found.', 'The record goes to the chosen base through the same intake as every other scrape: merged, never duplicated.', 'Extra searches (one per line in the configuration) follow one after another on your own Google domain, a few seconds apart; a place found by two searches is saved once.']),
  H2('26.2 What is read, and where from'),
  T(['Field', 'Source', 'Notes'], [
    ['Name', 'The card’s link label; the heading of the place page', ''],
    ['Category', 'The first text part after the rating; on the place page the category button', 'Opening-hours words (“Closed”, “Opens 8 am”, “Buka”, “Tutup”), prices and phone numbers are recognised and kept out'],
    ['Address', 'Text parts that look like an address (digits, commas, “Jl.”, “street” …); on the place page the address row', 'Strict on purpose: a part that does not look like an address is left out and the place page fills it in'],
    ['Phone', 'The card; the place page (the row id carries the number); only if Maps has none, a tel: or WhatsApp number from the website', ''],
    ['Website', 'The “Website” button; the place page’s website row', 'Google’s link wrapper is unwrapped, tracking parameters removed, Google’s own pages and Directions links are never taken'],
    ['E-mail', 'The business website: mailto links, Cloudflare-protected, “[at]” or entity-obfuscated, JSON-LD', 'Ranked: the site’s own domain first, then info@ / sales@ / contact@ …, free mail last; image names and placeholder addresses removed'],
    ['Social links', 'WhatsApp (wa.me), Facebook, Instagram, LinkedIn, X, YouTube, TikTok on the website', 'Share buttons are ignored'],
    ['Rating, reviews', 'The rating element’s label (“4.6 stars 102 Reviews”, “4,6 bintang 1.234 Ulasan”) or the digits “4.6(102)”, “4(10)”, “5.0(1.2K)”', ''],
    ['Opening hours, plus code, coordinates', 'The place page’s weekly table and plus-code row; the coordinates in the link', 'Only when the place page was opened'],
    ['Google Maps link', 'The place link without the map position and click parameters', 'The identity of the place – the same place always gives the same link'],
    ['Search', 'The words of the search that found the place', 'Hidden field'],
  ], [18, 44, 38]),
  H2('26.3 The Places base and duplicates'),
  P('The **Places** template (＋ Add base) has the fields in the order a sales list needs them – Name, Category, Address, Phone, Website, Email, Social Links – followed by Rating, Reviews, Opening Hours, Plus Code, Coordinates, Google Maps link, Search and the usual outreach fields. Any other base works as well: whatever matches a field by meaning is filled, and a “Label: value” pair fills a field of the same name (add a field called “Rating” to a Companies base and it fills).'),
  P('**Duplicates.** Branches of one chain share a website, often an e-mail address and sometimes a name, so the usual “same website” and “same e-mail” rules are present but **off** in a Places base. A place is a duplicate only when it has the same Maps link, the same name and phone number, or the same name and address. (Tested: two branches of one chain with one shared website are two records, and the website is read once.)'),
  H2('26.4 Settings'),
  T(['Setting', 'Meaning', 'Default'], [
    ['Open a place’s own page', 'Only when the card lacks a phone or address / always (slowest, most complete) / never (fastest)', 'Only when missing'],
    ['Visit each business’s website', 'Looks for e-mail, WhatsApp and social links', 'On'],
    ['More searches', 'One search per line, run after the one on screen', 'None'],
    ['Max places', 'All searches together', '400'],
    ['Max scroll rounds', 'Scrolls of the list per search', '40'],
    ['Delay between places', 'Applied after a place that needed a network request; places read from the list alone are not delayed', '1.2 – 2.6 s'],
  ], [28, 52, 20]),
  H2('26.5 Pace, limits and what it will not do'),
  ...B(['**One request at a time.** The list is read in your own tab; a place page is opened in a background tab only when needed; websites are fetched one after another with a timeout.', '**It stops at a consent page, a sign-in or a CAPTCHA** and says so; it never tries to get past one.', '**About 120 places per search.** Google Maps lists at most that many for one search. For a larger area add searches – the same words with a city or district. Places found twice are saved once.', '**Terms of use.** Google’s terms restrict automated collection from Maps. VierCRM reads only what your own tab shows, at a human pace, but you are responsible for using it within the terms that apply to you; the sanctioned route for large volumes is Google’s paid Places API, which this extension does not use.', '**Nothing is guessed.** A phone, website or e-mail that the page does not show stays empty.']),
  H2('26.6 Verified and not verified'),
  ...B(['**Verified** (Chromium, the real built extension, 158 unit tests and 104 browser checks): a look-alike of Maps whose structure follows the real one (a scrolling `role="feed"`, a `/maps/place/` link per entry, `data-item-id` rows on the place panel, obfuscated class names) – 20 places loaded in three scroll batches, English and Indonesian labels, cards without phone or website, whole-number ratings, only the incomplete card opened in its own tab, e-mail from a home page, a contact page and a Cloudflare-protected address, chain branches kept apart, a second search with one overlapping place, and nothing sent to Google during the test.', '**Not verified: the live google.com/maps.** Google changes its markup without notice. The reader relies on structure and text patterns instead of class names and uses several signals for each field, but it could not be run against the real site here. First thing to do on a real search: press **Preview** and compare the counts of places with phone, address and website against what you see; if a column is empty, the HTML of one card is enough to adjust `parseCard`.', '**Not verified:** how real small-business websites behave (heavy scripts, e-mail drawn as images, contact forms only) – those give no e-mail, by design.']),
  pageBreak());

// ---- appendices
add(H1('Appendix A – Test results'),
  P(`Built ${when}. Unit tests: **${unit.passed ?? '?'} passed of ${unit.total}**. Browser test: **${e2e.total - e2e.failed} passed of ${e2e.total}** checks (run ${e2e.at ? e2e.at.slice(0, 10) : 'n/a'}).`),
  H2('A.1 Unit tests (Vitest, fake IndexedDB, jsdom, scripted network)'),
  T(['File', 'Tests', 'Covers'], unit.files.map(f => [`\`${f.name}\``, String(f.n), (DESC[f.name]?.[1] || '').slice(0, 160)]), [30, 8, 62]),
  H2('A.2 Browser end-to-end checks'),
  P('The real built extension in Chromium against a fictional university site and fake research / e-mail services on localhost. No real service is contacted and no real e-mail can be sent.'),
  T(['#', 'Check', 'Result'], e2e.results.map((r, i) => [String(i + 1), r.name, r.ok ? 'pass' : 'FAIL']), [6, 84, 10]),
  H2('A.3 What these tests do not prove'),
  ...B(['That any real university site is detected correctly (only the fixtures were available).', 'That Brevo, Gmail, Unpaywall, Google Scholar or ResearchGate behave as the fakes do.', 'Performance on other computers: the benchmark is one machine and varies by about a factor of two between runs.']),
  pageBreak(),
  H1('Appendix B – Example workflows and samples'),
  H2('B.1 Scrape a directory'),
  ...N(['Open the staff directory in a tab. Click the VierCRM icon → **Scrape**.', '**Save to base**: Researchers (or Contacts, or **＋ New base…**). Configuration: “People directory (auto-detect)”. **Preview** shows who will be read.', '**Start → Researchers**. Watch the progress; use the floating control to pause. People appear in the base; duplicates are skipped; the new ones are researched automatically.', 'For a site that needs it: Edit configuration → untick automatic detection → ⌖ Pick a card → map extra fields → Pagination → **Save as new…**.']),
  H2('B.2 Publication lookup workflow'),
  ...N(['Automatic: nothing to do – records with a name and no publication fill themselves in. By hand: open a record → **Run research**.', 'The default chain runs: Latest Publication → Latest Research → Publication Date / URL / DOI / Access → Research Keywords (only if empty) → Publication File.', 'If the panel shows “Which one is this person?”, choose; the rest of the chain then continues.', 'Add your own field: Fields → **+ Add field** → “Abstract” (reads from Latest Publication); the Dependencies tab shows its place in the order.', 'Bulk: the “✦ Research this view” button, or Research Finder → “Research N now (without waiting)”.']),
  H2('B.3 PDF attachment workflow'),
  ...N(['After the publication is found, the Publication File field runs: source link → Unpaywall → OpenAlex → Europe PMC → arXiv → landing page.', 'A valid PDF is attached and shown as a card with download and open buttons; otherwise the cell says **Full text unavailable** and the record keeps the DOI and URLs.', 'To add a PDF yourself: record panel → “Attach a PDF I have”.']),
  H2('B.4 Example automation'),
  Code(JSON.stringify({ name: 'Introduce ourselves to contacts that are ready for outreach', enabled: false, testMode: true, trigger: { type: 'recordEntersView', viewId: 'view_ready' }, conditions: 'Email, Position, Institution not empty AND Outreach Status = Not Contacted', actions: ['runLookup', 'wait 30 s', 'sendEmail (tpl_intro, Brevo, info@vierapparatus.com)', 'changeStatus Outreach Status = Contacted'] }, null, 2)),
  P('The full file is `samples/automation-example.json`. Test it with “Test on 5 records”, read the history, then switch test mode off and turn it on.'),
  H2('B.5 E-mail integration configuration'),
  Code(['Brevo   Settings → API key → Verify sender (info@vierapparatus.com must be an ACTIVE Brevo sender)', '        Brevo account: enable open + click tracking for transactional e-mail', 'Gmail   Google Cloud: Gmail API on; OAuth client (Web application); redirect URI = https://<extension-id>.chromiumapp.org/', '        Gmail: Settings → Accounts → "Send mail as" info@vierapparatus.com (verified)', 'Webhook node backend/webhook-server.mjs  → tunnel → Brevo webhook: https://<tunnel>/brevo/webhook/<secret>', '        VierCRM Settings → Webhook backend: https://<tunnel> + token', 'Safety  Settings → Allow sending OFF until a test send looks right'].join('\n')),
  H2('B.6 Add a base and scrape a company list into it'),
  ...N(['Press **＋ Add base** in the left menu, choose **Companies**, name it (for example “Suppliers”), **Create base**.', 'Optional: open the base → **Fields** → **+ Add field** → “Revenue”. Any “Revenue: …” row on the pages will now fill it.', 'Open the supplier listing in a tab → VierCRM icon → **Save to base: Suppliers** → configuration “Companies / any listing” → **Preview** → **Start → Suppliers**.', 'To research the companies’ people later: Manage bases → Suppliers → **✦ Add research fields**.']),
  H2('B.7 Files in samples/'),
  T(['File', 'Purpose'], [['`sample-researchers.csv`', 'Twelve fictional researchers for Import CSV (`.example` addresses cannot be delivered).'], ['`scrape-config-example.json`', 'Manual-selector configuration with XPath mappings, constants and a Next selector.'], ['`automation-example.json`', 'The automation above.'], ['`email-template-example.json`', 'The introduction template.']], [38, 62]),
  H1('Appendix C – Message reference'),
  T(['Message', 'From → to', 'Purpose'], [['`scrape:start / pause / resume / stop / status`', 'page → worker', 'Control and observe a run'], ['`scrape:preview`, `picker:start / stop`', 'page → worker → tab', 'Detect preview, element picker'], ['`crawl:page`, `crawl:extractHere`, `detect:preview`', 'worker → content', 'Read a page / a hidden-tab profile'], ['`scrape:person`, `scrape:render`, `scrape:control`, `scrape:progress-lite`, `picker:result`, `widget:action`', 'content → worker', 'Report people, ask for a render, poll Stop / Pause'], ['`scrape:progress`, `picker:picked`', 'worker → pages / tab', 'Progress, picked selector'], ['`record:changed`', 'page → worker', 'Run the automation engine for a page’s change'], ['`lookup:run`, `lookup:many`, `lookup:progress`', 'page ↔ worker', 'Research one / many records'], ['`author:search`, `author:latest`', 'page → worker', 'Free author search and “latest work of this candidate”'], ['`auto:run`, `auto:retry`', 'page → worker', 'Manual / test run, retry'], ['`auto:now`, `auto:records`', 'page → worker', 'Run automatic research for a base now / for the records in the view being looked at'], ['`email:send`, `email:sync`, `email:verifyBrevo`, `gmail:connect`', 'page → worker', 'Test / real send, analytics sync, sender check, Gmail sign-in']], [44, 22, 34]));

// ------------------------------------------------------------------ assemble
const numbering = { config: [{ reference: 'bullets', levels: [{ level: 0, format: LevelFormat.BULLET, text: '•', alignment: AlignmentType.LEFT, style: { paragraph: { indent: { left: 540, hanging: 270 } } } }] }, { reference: 'numbers', levels: [{ level: 0, format: LevelFormat.DECIMAL, text: '%1.', alignment: AlignmentType.LEFT, style: { paragraph: { indent: { left: 540, hanging: 300 } } } }] }] };
const doc = new Document({
  creator: 'VierCRM', title: 'VierCRM Technical Documentation', description: 'Technical documentation of the VierCRM Chrome extension', numbering,
  styles: { default: { document: { run: { font: 'Calibri', size: 21 } } } },
  sections: [{ properties: { page: { size: { width: 11906, height: 16838 }, margin: { top: 1134, bottom: 1134, left: 1134, right: 1134 } } },
    headers: { default: new Header({ children: [new Paragraph({ children: [new TextRun({ text: 'VierCRM · Technical Documentation', font: 'Jost', size: 17, color: BLUE })] })] }) },
    footers: { default: new Footer({ children: [new Paragraph({ alignment: AlignmentType.CENTER, children: [new TextRun({ text: 'VierApparatus · page ', font: 'Calibri', size: 17, color: '77737A' }), new TextRun({ children: [PageNumber.CURRENT], font: 'Calibri', size: 17, color: '77737A' })] })] }) },
    children: c }],
});
fs.mkdirSync(path.dirname(OUT), { recursive: true });
const buf = await Packer.toBuffer(doc); fs.writeFileSync(OUT, buf);
console.log(`wrote ${path.relative(root, OUT)} (${(buf.length / 1024).toFixed(0)} KB, ${c.length} blocks, ${files.length} source files described)`);
